  1→import { nanoid } from "nanoid";
  2→import type { AgentInstance } from "../agents/agent-instance.js";
  3→import type { AgentCapabilities, AgentEvent, Attachment, PermissionRequest, SessionStatus, SessionMode, ConfigOption, ModelInfo, SessionModeState, SessionModelState } from "../types.js";
  4→import { TypedEmitter } from "../utils/typed-emitter.js";
  5→import { PromptQueue } from "./prompt-queue.js";
  6→import { PermissionGate } from "./permission-gate.js";
  7→import { createChildLogger, createSessionLogger, type Logger } from "../utils/log.js";
  8→import type { SpeechService } from "../../plugins/speech/exports.js";
  9→import type { MiddlewareChain } from "../plugin/middleware-chain.js";
 10→import * as fs from "node:fs";
 11→const moduleLog = createChildLogger({ module: "session" });
 12→
 13→// TTS constants
 14→export const TTS_PROMPT_INSTRUCTION = `\n\nAdditionally, include a [TTS]...[/TTS] block with a spoken-friendly summary of your response. Focus on key information, decisions the user needs to make, or actions required. The agent decides what to say and how long. Respond in the same language the user is using. This instruction applies to this message only.`;
 15→export const TTS_BLOCK_REGEX = /\[TTS\]([\s\S]*?)\[\/TTS\]/;
 16→export const TTS_MAX_LENGTH = 5000;
 17→export const TTS_TIMEOUT_MS = 30_000;
 18→
 19→// Valid state transitions: from → Set<to>
 20→const VALID_TRANSITIONS: Record<SessionStatus, Set<SessionStatus>> = {
 21→  initializing: new Set(["active", "error"]),
 22→  active: new Set(["error", "finished", "cancelled"]),
 23→  error: new Set(["active"]),
 24→  cancelled: new Set(["active"]),
 25→  finished: new Set(),
 26→};
 27→
 28→export interface SessionEvents {
 29→  agent_event: (event: AgentEvent) => void;
 30→  permission_request: (request: PermissionRequest) => void;
 31→  session_end: (reason: string) => void;
 32→  status_change: (from: SessionStatus, to: SessionStatus) => void;
 33→  named: (name: string) => void;
 34→  error: (error: Error) => void;
 35→}
 36→
 37→export class Session extends TypedEmitter<SessionEvents> {
 38→  id: string;
 39→  channelId: string;
 40→  threadId: string = "";
 41→  agentName: string;
 42→  workingDirectory: string;
 43→  agentInstance: AgentInstance;
 44→  agentSessionId: string = "";
 45→  private _status: SessionStatus = "initializing";
 46→  name?: string;
 47→  createdAt: Date = new Date();
 48→  voiceMode: "off" | "next" | "on" = "off";
 49→  dangerousMode: boolean = false;
 50→  currentMode?: string;
 51→  availableModes: SessionMode[] = [];
 52→  configOptions: ConfigOption[] = [];
 53→  currentModel?: string;
 54→  availableModels: ModelInfo[] = [];
 55→  agentCapabilities?: AgentCapabilities;
 56→  archiving: boolean = false;
 57→  promptCount: number = 0;
 58→  log: Logger;
 59→  middlewareChain?: MiddlewareChain;
 60→
 61→  readonly permissionGate = new PermissionGate();
 62→  private readonly queue: PromptQueue;
 63→  private speechService?: SpeechService;
 64→  private pendingContext: string | null = null;
 65→
 66→  constructor(opts: {
 67→    id?: string;
 68→    channelId: string;
 69→    agentName: string;
 70→    workingDirectory: string;
 71→    agentInstance: AgentInstance;
 72→    speechService?: SpeechService;
 73→  }) {
 74→    super();
 75→    this.id = opts.id || nanoid(12);
 76→    this.channelId = opts.channelId;
 77→    this.agentName = opts.agentName;
 78→    this.workingDirectory = opts.workingDirectory;
 79→    this.agentInstance = opts.agentInstance;
 80→    this.speechService = opts.speechService;
 81→    this.log = createSessionLogger(this.id, moduleLog);
 82→    this.log.info({ agentName: this.agentName }, "Session created");
 83→
 84→    this.queue = new PromptQueue(
 85→      (text, attachments) => this.processPrompt(text, attachments),
 86→      (err) => {
 87→        this.fail("Prompt execution failed");
 88→        this.log.error({ err }, "Prompt execution failed");
 89→      },
 90→    );
 91→  }
 92→
 93→  // --- State Machine ---
 94→
 95→  get status(): SessionStatus {
 96→    return this._status;
 97→  }
 98→
 99→
100→  /** Transition to active — from initializing, error, or cancelled */
101→  activate(): void {
102→    this.transition("active");
103→  }
104→
105→  /** Transition to error — from initializing or active */
106→  fail(reason: string): void {
107→    this.transition("error");
108→    this.emit("error", new Error(reason));
109→  }
110→
111→  /** Transition to finished — from active only. Emits session_end for backward compat. */
112→  finish(reason?: string): void {
113→    this.transition("finished");
114→    this.emit("session_end", reason ?? "completed");
115→  }
116→
117→  /** Transition to cancelled — from active only (terminal session cancel) */
118→  markCancelled(): void {
119→    this.transition("cancelled");
120→  }
121→
122→  private transition(to: SessionStatus): void {
123→    const from = this._status;
124→    const allowed = VALID_TRANSITIONS[from];
125→    if (!allowed?.has(to)) {
126→      throw new Error(
127→        `Invalid session transition: ${from} → ${to}`,
128→      );
129→    }
130→    this._status = to;
131→    this.log.debug({ from, to }, "Session status transition");
132→    this.emit("status_change", from, to);
133→  }
134→
135→  /** Number of prompts waiting in queue */
136→  get queueDepth(): number {
137→    return this.queue.pending;
138→  }
139→
140→  get promptRunning(): boolean {
141→    return this.queue.isProcessing;
142→  }
143→
144→  // --- Context Injection ---
145→
146→  setContext(markdown: string): void {
147→    this.pendingContext = markdown;
148→  }
149→
150→  // --- Voice Mode ---
151→
152→  setVoiceMode(mode: "off" | "next" | "on"): void {
153→    this.voiceMode = mode;
154→    this.log.info({ voiceMode: mode }, "TTS mode changed");
155→  }
156→
157→  // --- Public API ---
158→
159→  async enqueuePrompt(text: string, attachments?: Attachment[]): Promise<void> {
160→    // Hook: agent:beforePrompt — modifiable, can block
161→    if (this.middlewareChain) {
162→      const payload = { text, attachments, sessionId: this.id };
163→      const result = await this.middlewareChain.execute('agent:beforePrompt', payload, async (p) => p);
164→      if (!result) return; // blocked by middleware
165→      text = result.text;
166→      attachments = result.attachments;
167→    }
168→    await this.queue.enqueue(text, attachments);
169→  }
170→
171→  private async processPrompt(text: string, attachments?: Attachment[]): Promise<void> {
172→    if (text === "\x00__warmup__") {
173→      await this.runWarmup();
174→      return;
175→    }
176→
177→    this.promptCount++;
178→
179→    if (this._status === "initializing") {
180→      this.activate();
181→    }
182→    const promptStart = Date.now();
183→    this.log.debug("Prompt execution started");
184→
185→    // Context injection: prepend on first real prompt only
186→    if (this.pendingContext) {
187→      text = `[CONVERSATION HISTORY - This is context from previous sessions, not current conversation]\n\n${this.pendingContext}\n\n[END CONVERSATION HISTORY]\n\n${text}`;
188→      this.pendingContext = null;
189→      this.log.debug("Context injected into prompt");
190→    }
191→
192→    // STT: transcribe audio attachments if agent doesn't support audio
193→    const processed = await this.maybeTranscribeAudio(text, attachments);
194→
195→    // TTS: determine if TTS is active for this prompt
196→    const ttsActive =
197→      this.voiceMode !== "off" &&
198→      !!this.speechService?.isTTSAvailable();
199→
200→    // TTS: inject prompt instruction
201→    if (ttsActive) {
202→      processed.text += TTS_PROMPT_INSTRUCTION;
203→      if (this.voiceMode === "next") {
204→        this.voiceMode = "off";
205→      }
206→    }
207→
208→    // TTS: set up text accumulator before prompting
209→    let accumulatedText = "";
210→    const accumulatorListener = ttsActive
211→      ? (event: AgentEvent) => {
212→          if (event.type === "text") {
213→            accumulatedText += event.content;
214→          }
215→        }
216→      : null;
217→
218→    if (accumulatorListener) {
219→      this.on("agent_event", accumulatorListener);
220→    }
221→
222→    // Hook: turn:start — read-only, fire-and-forget
223→    if (this.middlewareChain) {
224→      this.middlewareChain.execute('turn:start', { sessionId: this.id, promptText: processed.text, promptNumber: this.promptCount }, async (p) => p).catch(() => {});
225→    }
226→
227→    let stopReason: string = 'end_turn';
228→    try {
229→      const response = await this.agentInstance.prompt(processed.text, processed.attachments);
230→      if (response && typeof response === 'object' && 'stopReason' in response) {
231→        stopReason = (response as { stopReason?: string }).stopReason ?? 'end_turn';
232→      }
233→    } finally {
234→      if (accumulatorListener) {
235→        this.off("agent_event", accumulatorListener);
236→      }
237→    }
238→
239→    // Hook: turn:end — read-only, fire-and-forget
240→    if (this.middlewareChain) {
241→      this.middlewareChain.execute('turn:end', { sessionId: this.id, stopReason: stopReason as import('../types.js').StopReason, durationMs: Date.now() - promptStart }, async (p) => p).catch(() => {});
242→    }
243→
244→    this.log.info(
245→      { durationMs: Date.now() - promptStart },
246→      "Prompt execution completed",
247→    );
248→
249→    // TTS: fire-and-forget post-response synthesis
250→    if (ttsActive && accumulatedText) {
251→      this.processTTSResponse(accumulatedText).catch((err) => {
252→        this.log.warn({ err }, "TTS post-processing failed");
253→      });
254→    }
255→
256→    if (!this.name) {
257→      await this.autoName();
258→    }
259→  }
260→
261→  private async maybeTranscribeAudio(
262→    text: string,
263→    attachments?: Attachment[],
264→  ): Promise<{ text: string; attachments?: Attachment[] }> {
265→    if (!attachments?.length || !this.speechService) {
266→      return { text, attachments };
267→    }
268→
269→    const hasAudioCapability = this.agentInstance.promptCapabilities?.audio === true;
270→    if (hasAudioCapability) {
271→      return { text, attachments };
272→    }
273→
274→    if (!this.speechService.isSTTAvailable()) {
275→      return { text, attachments };
276→    }
277→
278→    let transcribedText = text;
279→    const remainingAttachments: Attachment[] = [];
280→
281→    for (const att of attachments) {
282→      if (att.type !== "audio") {
283→        remainingAttachments.push(att);
284→        continue;
285→      }
286→
287→      try {
288→        const audioPath = att.originalFilePath || att.filePath;
289→        const audioMime = att.originalFilePath ? "audio/ogg" : att.mimeType;
290→        const audioBuffer = await fs.promises.readFile(audioPath);
291→        const result = await this.speechService.transcribe(audioBuffer, audioMime);
292→        this.log.info({ provider: "stt", duration: result.duration }, "Voice transcribed");
293→        // Notify user of transcription result
294→        this.emit("agent_event", {
295→          type: "system_message",
296→          message: `🎤 You said: ${result.text}`,
297→        });
298→        // Strip [Audio: ...] placeholder since we have the transcription
299→        transcribedText = transcribedText.replace(/\[Audio:\s*[^\]]*\]\s*/g, "").trim();
300→        transcribedText = transcribedText
301→          ? `${transcribedText}\n${result.text}`
302→          : result.text;
303→      } catch (err) {
304→        this.log.warn({ err }, "STT transcription failed, keeping audio attachment");
305→        this.emit("agent_event", {
306→          type: "error",
307→          message: `Voice transcription failed: ${(err as Error).message}`,
308→        });
309→        remainingAttachments.push(att);
310→      }
311→    }
312→
313→    return {
314→      text: transcribedText,
315→      attachments: remainingAttachments.length > 0 ? remainingAttachments : undefined,
316→    };
317→  }
318→
319→  private async processTTSResponse(responseText: string): Promise<void> {
320→    const match = TTS_BLOCK_REGEX.exec(responseText);
321→    if (!match?.[1]) {
322→      this.log.debug("No [TTS] block found in response, skipping synthesis");
323→      return;
324→    }
325→
326→    let ttsText = match[1].trim();
327→    if (!ttsText) return;
328→
329→    if (ttsText.length > TTS_MAX_LENGTH) {
330→      ttsText = ttsText.slice(0, TTS_MAX_LENGTH);
331→    }
332→
333→    try {
334→      const timeoutPromise = new Promise<never>((_, reject) =>
335→        setTimeout(() => reject(new Error("TTS synthesis timed out")), TTS_TIMEOUT_MS),
336→      );
337→      const result = await Promise.race([
338→        this.speechService!.synthesize(ttsText),
339→        timeoutPromise,
340→      ]);
341→      const base64 = result.audioBuffer.toString("base64");
342→      this.emit("agent_event", {
343→        type: "audio_content",
344→        data: base64,
345→        mimeType: result.mimeType,
346→      });
347→      this.log.info("TTS synthesis completed");
348→    } catch (err) {
349→      this.log.warn({ err }, "TTS synthesis failed, skipping");
350→    }
351→  }
352→
353→  // NOTE: This injects a summary prompt into the agent's conversation history.
354→  private async autoName(): Promise<void> {
355→    let title = "";
356→
357→    // Temporarily remove all agent_event listeners so auto-name output
358→    // is not forwarded to the adapter. Add a capture-only listener instead.
359→    const captureHandler = (event: AgentEvent) => {
360→      if (event.type === "text") title += event.content;
361→      // Swallow all other events from auto-name prompt
362→    };
363→
364→    // Pause the session emitter so agent_event emissions from SessionBridge
365→    // don't reach the adapter during auto-name. The AgentInstance emitter
366→    // stays active — we just intercept with our capture handler.
367→    this.pause((event) => event !== "agent_event");
368→    this.agentInstance.on("agent_event", captureHandler);
369→
370→    try {
371→      await this.agentInstance.prompt(
372→        "Summarize this conversation in max 5 words for a topic title. Reply ONLY with the title, nothing else.",
373→      );
374→      this.name = title.trim().slice(0, 50) || `Session ${this.id.slice(0, 6)}`;
375→      this.log.info({ name: this.name }, "Session auto-named");
376→
377→      // Emit named event — SessionBridge listens to rename the thread
378→      this.emit("named", this.name);
379→    } catch {
380→      this.name = `Session ${this.id.slice(0, 6)}`;
381→    } finally {
382→      this.agentInstance.off("agent_event", captureHandler);
383→      // Discard buffered auto-name agent_events, then resume normal delivery
384→      this.clearBuffer();
385→      this.resume();
386→    }
387→  }
388→
389→  async generateSummary(timeoutMs = 15000): Promise<string> {
390→    let summary = "";
391→    let timer: ReturnType<typeof setTimeout> | undefined;
392→
393→    const captureHandler = (event: AgentEvent) => {
394→      if (event.type === "text") summary += event.content;
395→    };
396→
397→    this.pause((event) => event !== "agent_event");
398→    this.agentInstance.on("agent_event", captureHandler);
399→
400→    try {
401→      const promptPromise = this.agentInstance.prompt(
402→        "Summarize what you've accomplished so far in this session in 2-3 sentences. Include: key files changed, decisions made, and current status. Reply ONLY with the summary, nothing else.",
403→      );
404→      const timeoutPromise = new Promise<void>((_, reject) => {
405→        timer = setTimeout(() => reject(new Error("summary timeout")), timeoutMs);
406→      });
407→      await Promise.race([promptPromise, timeoutPromise]);
408→      return summary.trim().slice(0, 500);
409→    } catch {
410→      this.log.warn("Failed to generate session summary");
411→      return "";
412→    } finally {
413→      if (timer) clearTimeout(timer);
414→      this.agentInstance.off("agent_event", captureHandler);
415→      this.clearBuffer();
416→      this.resume();
417→    }
418→  }
419→
420→  /** Fire-and-forget warm-up: primes model cache while user types their first message */
421→  async warmup(): Promise<void> {
422→    // Route through PromptQueue to prevent concurrent prompt execution.
423→    // Any user prompts arriving during warmup will be queued and drained after.
424→    await this.queue.enqueue("\x00__warmup__");
425→  }
426→
427→  private async runWarmup(): Promise<void> {
428→    // Pause events but let commands_update pass through
429→    this.pause((_event, args) => {
430→      const agentEvent = args[0] as AgentEvent;
431→      return agentEvent?.type === "commands_update";
432→    });
433→
434→    try {
435→      const start = Date.now();
436→      await this.agentInstance.prompt('Reply with only "ready".');
437→      this.activate();
438→      this.log.info({ durationMs: Date.now() - start }, "Warm-up complete");
439→    } catch (err) {
440→      this.log.error({ err }, "Warm-up failed");
441→    } finally {
442→      this.clearBuffer();
443→      this.resume();
444→    }
445→  }
446→
447→  // --- ACP Mode / Config / Model State ---
448→
449→  setInitialAcpState(state: {
450→    modes?: SessionModeState | null;
451→    configOptions?: ConfigOption[] | null;
452→    models?: SessionModelState | null;
453→    agentCapabilities?: AgentCapabilities | null;
454→  }): void {
455→    if (state.modes) {
456→      this.currentMode = state.modes.currentModeId;
457→      this.availableModes = state.modes.availableModes;
458→    }
459→    if (state.configOptions) {
460→      this.configOptions = state.configOptions;
461→    }
462→    if (state.models) {
463→      this.currentModel = state.models.currentModelId;
464→      this.availableModels = state.models.availableModels;
465→    }
466→    if (state.agentCapabilities) {
467→      this.agentCapabilities = state.agentCapabilities;
468→    }
469→  }
470→
471→  /** Set session name explicitly and emit 'named' event */
472→  setName(name: string): void {
473→    this.name = name;
474→    this.emit("named", name);
475→  }
476→
477→  async updateMode(modeId: string): Promise<void> {
478→    // Hook: mode:beforeChange — await-able, can block
479→    if (this.middlewareChain) {
480→      const result = await this.middlewareChain.execute('mode:beforeChange', { sessionId: this.id, fromMode: this.currentMode, toMode: modeId }, async (p) => p);
481→      if (!result) return; // blocked by middleware
482→    }
483→    this.currentMode = modeId;
484→  }
485→
486→  async updateConfigOptions(options: ConfigOption[]): Promise<void> {
487→    // Hook: config:beforeChange — await-able, can block
488→    if (this.middlewareChain) {
489→      const result = await this.middlewareChain.execute('config:beforeChange', { sessionId: this.id, configId: 'options', oldValue: this.configOptions, newValue: options }, async (p) => p);
490→      if (!result) return; // blocked by middleware
491→    }
492→    this.configOptions = options;
493→  }
494→
495→  async updateModel(modelId: string): Promise<void> {
496→    // Hook: model:beforeChange — await-able, can block
497→    if (this.middlewareChain) {
498→      const result = await this.middlewareChain.execute('model:beforeChange', { sessionId: this.id, fromModel: this.currentModel, toModel: modelId }, async (p) => p);
499→      if (!result) return; // blocked by middleware
500→    }
501→    this.currentModel = modelId;
502→  }
503→
504→  /** Cancel the current prompt and clear the queue. Stays in active state. */
505→  async abortPrompt(): Promise<void> {
506→    // Hook: agent:beforeCancel — modifiable, can block
507→    if (this.middlewareChain) {
508→      const result = await this.middlewareChain.execute('agent:beforeCancel', { sessionId: this.id }, async (p) => p);
509→      if (!result) return; // blocked by middleware
510→    }
511→    this.queue.clear();
512→    this.log.info("Prompt aborted");
513→    await this.agentInstance.cancel();
514→  }
515→
516→  async destroy(): Promise<void> {
517→    this.log.info("Session destroyed");
518→    await this.agentInstance.destroy();
519→  }
520→}
