  1→import fs from "node:fs";
  2→import path from "node:path";
  3→import type { SessionRecord } from "../types.js";
  4→import { createChildLogger } from "../utils/log.js";
  5→
  6→const log = createChildLogger({ module: "session-store" });
  7→
  8→export interface SessionStore {
  9→  save(record: SessionRecord): Promise<void>;
 10→  get(sessionId: string): SessionRecord | undefined;
 11→  findByPlatform(
 12→    channelId: string,
 13→    predicate: (platform: Record<string, unknown>) => boolean,
 14→  ): SessionRecord | undefined;
 15→  findByAgentSessionId(agentSessionId: string): SessionRecord | undefined;
 16→  list(channelId?: string): SessionRecord[];
 17→  remove(sessionId: string): Promise<void>;
 18→}
 19→
 20→interface StoreFile {
 21→  version: number;
 22→  sessions: Record<string, SessionRecord>;
 23→}
 24→
 25→const DEBOUNCE_MS = 2000;
 26→
 27→export class JsonFileSessionStore implements SessionStore {
 28→  private records: Map<string, SessionRecord> = new Map();
 29→  private filePath: string;
 30→  private ttlDays: number;
 31→  private debounceTimer: ReturnType<typeof setTimeout> | null = null;
 32→  private cleanupInterval: ReturnType<typeof setInterval> | null = null;
 33→  private flushHandler: (() => void) | null = null;
 34→
 35→  constructor(filePath: string, ttlDays: number) {
 36→    this.filePath = filePath;
 37→    this.ttlDays = ttlDays;
 38→    this.load();
 39→    this.cleanup();
 40→
 41→    // Daily cleanup for long-running instances
 42→    this.cleanupInterval = setInterval(
 43→      () => this.cleanup(),
 44→      24 * 60 * 60 * 1000,
 45→    );
 46→
 47→    // Force flush on shutdown
 48→    this.flushHandler = () => this.flushSync();
 49→    process.on("SIGTERM", this.flushHandler);
 50→    process.on("SIGINT", this.flushHandler);
 51→    process.on("exit", this.flushHandler);
 52→  }
 53→
 54→  async save(record: SessionRecord): Promise<void> {
 55→    this.records.set(record.sessionId, { ...record });
 56→    this.scheduleDiskWrite();
 57→  }
 58→
 59→  get(sessionId: string): SessionRecord | undefined {
 60→    return this.records.get(sessionId);
 61→  }
 62→
 63→  findByPlatform(
 64→    channelId: string,
 65→    predicate: (platform: Record<string, unknown>) => boolean,
 66→  ): SessionRecord | undefined {
 67→    for (const record of this.records.values()) {
 68→      if (record.channelId === channelId && predicate(record.platform)) {
 69→        return record;
 70→      }
 71→    }
 72→    return undefined;
 73→  }
 74→
 75→  findByAgentSessionId(agentSessionId: string): SessionRecord | undefined {
 76→    return [...this.records.values()].find(
 77→      (r) =>
 78→        r.agentSessionId === agentSessionId ||
 79→        r.originalAgentSessionId === agentSessionId,
 80→    );
 81→  }
 82→
 83→  list(channelId?: string): SessionRecord[] {
 84→    const all = [...this.records.values()];
 85→    if (channelId) return all.filter((r) => r.channelId === channelId);
 86→    return all;
 87→  }
 88→
 89→  async remove(sessionId: string): Promise<void> {
 90→    this.records.delete(sessionId);
 91→    this.scheduleDiskWrite();
 92→  }
 93→
 94→  flushSync(): void {
 95→    if (this.debounceTimer) {
 96→      clearTimeout(this.debounceTimer);
 97→      this.debounceTimer = null;
 98→    }
 99→    const data: StoreFile = {
100→      version: 1,
101→      sessions: Object.fromEntries(this.records),
102→    };
103→    const dir = path.dirname(this.filePath);
104→    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
105→    fs.writeFileSync(this.filePath, JSON.stringify(data, null, 2));
106→  }
107→
108→  destroy(): void {
109→    if (this.debounceTimer) clearTimeout(this.debounceTimer);
110→    if (this.cleanupInterval) clearInterval(this.cleanupInterval);
111→    if (this.flushHandler) {
112→      process.removeListener("SIGTERM", this.flushHandler);
113→      process.removeListener("SIGINT", this.flushHandler);
114→      process.removeListener("exit", this.flushHandler);
115→      this.flushHandler = null;
116→    }
117→  }
118→
119→  private load(): void {
120→    if (!fs.existsSync(this.filePath)) return;
121→    try {
122→      const raw = JSON.parse(
123→        fs.readFileSync(this.filePath, "utf-8"),
124→      ) as StoreFile;
125→      if (raw.version !== 1) {
126→        log.warn(
127→          { version: raw.version },
128→          "Unknown session store version, skipping load",
129→        );
130→        return;
131→      }
132→      for (const [id, record] of Object.entries(raw.sessions)) {
133→        this.records.set(id, record);
134→      }
135→      log.debug({ count: this.records.size }, "Loaded session records");
136→    } catch (err) {
137→      log.error({ err }, "Failed to load session store");
138→    }
139→  }
140→
141→  private cleanup(): void {
142→    const cutoff = Date.now() - this.ttlDays * 24 * 60 * 60 * 1000;
143→    let removed = 0;
144→    for (const [id, record] of this.records) {
145→      if (record.status === "active" || record.status === "initializing")
146→        continue;
147→      const lastActive = new Date(record.lastActiveAt).getTime();
148→      if (lastActive < cutoff) {
149→        this.records.delete(id);
150→        removed++;
151→      }
152→    }
153→    if (removed > 0) {
154→      log.info({ removed }, "Cleaned up expired session records");
155→      this.scheduleDiskWrite();
156→    }
157→  }
158→
159→  private scheduleDiskWrite(): void {
160→    if (this.debounceTimer) clearTimeout(this.debounceTimer);
161→    this.debounceTimer = setTimeout(() => {
162→      this.flushSync();
163→    }, DEBOUNCE_MS);
164→  }
165→}
