104→
105→    // Initialize plugin lifecycle manager (before setting middlewareChain on factory)
106→    this.lifecycleManager = new LifecycleManager({
107→      serviceRegistry: new ServiceRegistry(),
108→      middlewareChain: new MiddlewareChain(),
109→      errorTracker: new ErrorTracker(),
110→      eventBus: this.eventBus as any,
111→      sessions: this.sessionManager,
112→      config: this.configManager,
113→      core: this,
114→      storagePath: path.join(os.homedir(), ".openacp", "plugins", "data"),
115→    });
116→
117→    // Wire middleware chain to session factory and session manager
118→    this.sessionFactory.middlewareChain = this.lifecycleManager.middlewareChain;
119→    this.sessionManager.middlewareChain = this.lifecycleManager.middlewareChain;
120→
121→    // Hot-reload: handle config changes that need side effects
122→    this.configManager.on(
123→      "config:changed",
124→      async ({ path: configPath, value }: { path: string; value: unknown }) => {
125→        if (configPath === "logging.level" && typeof value === "string") {
126→          const { setLogLevel } = await import("./utils/log.js");
127→          setLogLevel(value);
128→          log.info({ level: value }, "Log level changed at runtime");
129→        }
130→        if (configPath.startsWith("speech.")) {
131→          const speechSvc = this.speechService;
132→          if (speechSvc) {
133→            const { GroqSTT, EdgeTTS } = await import("../plugins/speech/exports.js");
134→            const newConfig = this.configManager.get();
135→            const newSpeechConfig = newConfig.speech ?? {
136→              stt: { provider: null, providers: {} },
137→              tts: { provider: null, providers: {} },
138→            };
139→            speechSvc.updateConfig(newSpeechConfig);
140→            const groqCfg = newSpeechConfig.stt?.providers?.groq;
141→            if (groqCfg?.apiKey) {
142→              speechSvc.registerSTTProvider(
143→                "groq",
144→                new GroqSTT(groqCfg.apiKey, groqCfg.model),
145→              );
146→            }
147→            // Re-register TTS providers on config change — always keep edge-tts available
148→            {
149→              const edgeConfig = newSpeechConfig.tts?.providers?.["edge-tts"];
150→              const voice = edgeConfig?.voice as string | undefined;
151→              speechSvc.registerTTSProvider("edge-tts", new EdgeTTS(voice));
152→            }
153→            log.info("Speech service config updated at runtime");
154→          }
155→        }
156→      },
157→    );
158→  }
