182→  async stop(): Promise<void> {
183→    // 1. Notify users
184→    try {
185→      await this.notificationManager.notifyAll({
186→        sessionId: "system",
187→        type: "error",
188→        summary: "OpenACP is shutting down",
189→      });
190→    } catch {
191→      /* best effort */
192→    }
193→
194→    // 2. Destroy all sessions
195→    await this.sessionManager.destroyAll();
196→
197→    // 3. Stop adapters
198→    for (const adapter of this.adapters.values()) {
199→      await adapter.stop();
200→    }
201→
202→    // 4. Cleanup usage store
203→    if (this.usageStore) {
204→      this.usageStore.destroy();
205→    }
206→  }
207→
208→  // --- Summary ---
209→
210→  async summarizeSession(sessionId: string): Promise<{ ok: true; summary: string } | { ok: false; error: string }> {
211→    // Active session — summarize directly
212→    const session = this.sessionManager.getSession(sessionId);
213→    if (session && session.status === "active") {
214→      try {
215→        const summary = await session.generateSummary();
216→        if (!summary) return { ok: false, error: "Agent could not generate summary" };
217→        return { ok: true, summary };
218→      } catch (err) {
219→        return { ok: false, error: (err as Error).message };
220→      }
221→    }
222→
223→    // Ended session — respawn agent temporarily with conversation history
224→    const record = this.sessionManager.getSessionRecord(sessionId);
225→    if (!record?.agentSessionId) {
226→      return { ok: false, error: "Session not found or has no agent history" };
227→    }
228→
229→    const caps = getAgentCapabilities(record.agentName);
230→    if (!caps.supportsResume) {
231→      return { ok: false, error: `Agent "${record.agentName}" does not support resume — cannot summarize ended session` };
232→    }
233→
234→    let tempSession: Session | undefined;
235→    try {
236→      const agentInstance = await this.agentManager.resume(
237→        record.agentName,
238→        record.workingDir,
239→        record.agentSessionId,
240→      );
241→
242→      tempSession = new Session({
243→        id: `summary-${sessionId}`,
244→        channelId: record.channelId,
245→        agentName: record.agentName,
246→        workingDirectory: record.workingDir,
247→        agentInstance,
248→      });
249→      tempSession.activate();
250→
251→      const summary = await tempSession.generateSummary();
252→      if (!summary) return { ok: false, error: "Agent could not generate summary" };
253→      return { ok: true, summary };
254→    } catch (err) {
255→      return { ok: false, error: (err as Error).message };
256→    } finally {
257→      if (tempSession) {
258→        try { await tempSession.destroy(); } catch { /* best effort */ }
259→      }
260→    }
261→  }
262→
263→  // --- Archive ---
264→
265→  async archiveSession(sessionId: string): Promise<{ ok: true } | { ok: false; error: string }> {
266→    const session = this.sessionManager.getSession(sessionId);
267→    const record = this.sessionManager.getSessionRecord(sessionId);
268→
269→    if (!session && !record) return { ok: false, error: "Session not found" };
270→
271→    const channelId = session?.channelId ?? record?.channelId;
272→    if (!channelId) return { ok: false, error: "No channel for session" };
273→
274→    const adapter = this.adapters.get(channelId);
275→    if (!adapter) return { ok: false, error: "Adapter not found for session" };
276→
277→    try {
278→      // 1. Delete topic — if session is in memory use archiveSessionTopic (cleans up trackers),
279→      //    otherwise use deleteSessionThread (looks up topicId from record)
280→      if (session) {
281→        await adapter.archiveSessionTopic?.(session.id);
282→      } else {
283→        await adapter.deleteSessionThread?.(sessionId);
284→      }
285→
286→      // 2. Cancel the session if in memory (stop agent)
287→      if (session) {
288→        try {
289→          await this.sessionManager.cancelSession(sessionId);
290→        } catch {
291→          // Session may already be finished/cancelled
292→        } finally {
293→          // Clear archiving flag after cancel completes — prevents race window
294→          // where agent events try to send to deleted topic
295→          session.archiving = false;
296→        }
297→      }
298→
299→      // 3. Remove session record
300→      await this.sessionManager.removeRecord(sessionId);
301→
302→      return { ok: true };
303→    } catch (err) {
304→      // Clear archiving flag on error too
305→      if (session) session.archiving = false;
306→      return { ok: false, error: (err as Error).message };
307→    }
308→  }
309→
310→  // --- Message Routing ---
311→
312→  async handleMessage(message: IncomingMessage): Promise<void> {
313→    log.debug(
314→      {
315→        channelId: message.channelId,
316→        threadId: message.threadId,
317→        userId: message.userId,
318→      },
319→      "Incoming message",
320→    );
321→
322→    // Hook: message:incoming — modifiable, can block
323→    if (this.lifecycleManager?.middlewareChain) {
324→      const result = await this.lifecycleManager.middlewareChain.execute(
325→        'message:incoming',
326→        message,
327→        async (msg) => msg,
328→      );
329→      if (!result) return; // blocked by middleware
330→      message = result;
331→    }
332→
333→    // Security: check user access and session limits
334→    const access = this.securityGuard.checkAccess(message);
335→    if (!access.allowed) {
336→      log.warn({ userId: message.userId, reason: access.reason }, "Access denied");
337→      if (access.reason.includes("Session limit")) {
338→        const adapter = this.adapters.get(message.channelId);
339→        if (adapter) {
340→          await adapter.sendMessage(message.threadId, {
341→            type: "error",
342→            text: `⚠️ ${access.reason}. Please cancel existing sessions with /cancel before starting new ones.`,
343→          });
344→        }
345→      }
346→      return;
347→    }
348→
349→    // Find session by thread
350→    let session = this.sessionManager.getSessionByThread(
351→      message.channelId,
352→      message.threadId,
353→    );
354→
355→    // Lazy resume: try to restore session from store
356→    if (!session) {
357→      session = (await this.lazyResume(message)) ?? undefined;
358→    }
359→
360→    if (!session) {
361→      log.warn(
362→        { channelId: message.channelId, threadId: message.threadId },
363→        "No session found for thread (in-memory miss + lazy resume returned null)",
364→      );
365→      return;
366→    }
367→
368→    // Update activity timestamp
369→    this.sessionManager.patchRecord(session.id, {
370→      lastActiveAt: new Date().toISOString(),
371→    });
372→
373→    // Forward to session
374→    await session.enqueuePrompt(message.text, message.attachments);
375→  }
376→
377→  // --- Unified Session Creation Pipeline ---
378→
379→  async createSession(params: {
380→    channelId: string;
381→    agentName: string;
382→    workingDirectory: string;
383→    resumeAgentSessionId?: string;
384→    existingSessionId?: string;
385→    createThread?: boolean;
386→    initialName?: string;
387→  }): Promise<Session> {
388→    // 1-3. Spawn/resume agent, create Session, register in SessionManager
389→    const session = await this.sessionFactory.create(params);
390→
391→    // 4. Create thread if needed
392→    const adapter = this.adapters.get(params.channelId);
393→    if (params.createThread && adapter) {
394→      const threadId = await adapter.createSessionThread(
395→        session.id,
396→        params.initialName ?? `🔄 ${params.agentName} — New Session`,
397→      );
398→      session.threadId = threadId;
399→    }
400→
401→    // 5. Connect SessionBridge
402→    if (adapter) {
403→      const bridge = this.createBridge(session, adapter);
404→      bridge.connect();
405→    }
406→
407→    // 5b-5c. Wire usage tracking and tunnel cleanup
408→    this.sessionFactory.wireSideEffects(session, {
409→      usageStore: this.usageStore,
410→      usageBudget: this.usageBudget,
411→      notificationManager: this.notificationManager,
412→      tunnelService: this._tunnelService,
413→    });
414→
415→    // 6. Persist initial record
416→    // Preserve existing platform data (e.g. topicId) when resuming an existing session
417→    const existingRecord = this.sessionStore?.get(session.id);
418→    const platform: Record<string, unknown> = {
419→      ...(existingRecord?.platform ?? {}),
420→    };
421→    if (session.threadId) {
422→      if (params.channelId === "telegram") {
423→        platform.topicId = Number(session.threadId);
424→      } else {
425→        platform.threadId = session.threadId;
426→      }
427→    }
428→    await this.sessionManager.patchRecord(session.id, {
429→      sessionId: session.id,
430→      agentSessionId: session.agentSessionId,
431→      agentName: params.agentName,
432→      workingDir: params.workingDirectory,
433→      channelId: params.channelId,
434→      status: session.status,
435→      createdAt: session.createdAt.toISOString(),
436→      lastActiveAt: new Date().toISOString(),
437→      name: session.name,
438→      platform,
439→    });
440→
441→    log.info(
442→      { sessionId: session.id, agentName: params.agentName },
443→      "Session created via pipeline",
444→    );
445→    return session;
446→  }
