470→  async adoptSession(
471→    agentName: string,
472→    agentSessionId: string,
473→    cwd: string,
474→    channelId?: string,
475→  ): Promise<
476→    | {
477→        ok: true;
478→        sessionId: string;
479→        threadId: string;
480→        status: "adopted" | "existing";
481→      }
482→    | { ok: false; error: string; message: string }
483→  > {
484→    // 1. Validate agent supports resume
485→    const caps = getAgentCapabilities(agentName);
486→    if (!caps.supportsResume) {
487→      return {
488→        ok: false,
489→        error: "agent_not_supported",
490→        message: `Agent '${agentName}' does not support session resume`,
491→      };
492→    }
493→
494→    const agentDef = this.agentManager.getAgent(agentName);
495→    if (!agentDef) {
496→      return {
497→        ok: false,
498→        error: "agent_not_supported",
499→        message: `Agent '${agentName}' not found`,
500→      };
501→    }
502→
503→    // 2. Validate cwd
504→    const { existsSync } = await import("node:fs");
505→    if (!existsSync(cwd)) {
506→      return {
507→        ok: false,
508→        error: "invalid_cwd",
509→        message: `Directory does not exist: ${cwd}`,
510→      };
511→    }
512→
513→    // 3. Check session limit
514→    const maxSessions = this.configManager.get().security.maxConcurrentSessions;
515→    if (this.sessionManager.listSessions().length >= maxSessions) {
516→      return {
517→        ok: false,
518→        error: "session_limit",
519→        message: "Maximum concurrent sessions reached",
520→      };
521→    }
522→
523→    // 4. Check if session already exists on the same channel
524→    const existingRecord =
525→      this.sessionManager.getRecordByAgentSessionId(agentSessionId);
526→    if (existingRecord) {
527→      const sameChannel = !channelId || existingRecord.channelId === channelId;
528→      const platform = existingRecord.platform as { topicId?: number; threadId?: string } | undefined;
529→      const existingThreadId = platform?.topicId ? String(platform.topicId) : platform?.threadId;
530→      if (existingThreadId && sameChannel) {
531→        const adapter = this.adapters.get(existingRecord.channelId) ?? this.adapters.values().next().value;
532→        if (adapter) {
533→          try {
534→            await adapter.sendMessage(existingRecord.sessionId, {
535→              type: "text",
536→              text: "Session resumed from CLI.",
537→            });
538→          } catch { /* Topic/thread may be deleted */ }
539→        }
540→        return {
541→          ok: true,
542→          sessionId: existingRecord.sessionId,
543→          threadId: existingThreadId,
544→          status: "existing",
545→        };
546→      }
547→    }
548→
549→    // 5. Find adapter (explicit channel or default first)
550→    let adapterChannelId: string;
551→    if (channelId) {
552→      if (!this.adapters.has(channelId)) {
553→        const available = Array.from(this.adapters.keys()).join(", ") || "none";
554→        return { ok: false, error: "adapter_not_found", message: `Adapter '${channelId}' is not connected. Available: ${available}` };
555→      }
556→      adapterChannelId = channelId;
557→    } else {
558→      const firstEntry = this.adapters.entries().next().value;
559→      if (!firstEntry) {
560→        return { ok: false, error: "no_adapter", message: "No channel adapter registered" };
561→      }
562→      adapterChannelId = firstEntry[0];
563→    }
564→
565→    // 6. Create session via unified pipeline
566→    let session: Session;
567→    try {
568→      session = await this.createSession({
569→        channelId: adapterChannelId,
570→        agentName,
571→        workingDirectory: cwd,
572→        resumeAgentSessionId: agentSessionId,
573→        createThread: true,
574→        initialName: "Adopted session",
575→      });
576→    } catch (err) {
577→      return {
578→        ok: false,
579→        error: "resume_failed",
580→        message: `Failed to resume session: ${err instanceof Error ? err.message : String(err)}`,
581→      };
582→    }
583→
584→    // 7. Update store with adopt-specific fields
585→    const adoptPlatform: Record<string, unknown> = {};
586→    if (adapterChannelId === 'telegram') {
587→      adoptPlatform.topicId = Number(session.threadId);
588→    } else {
589→      adoptPlatform.threadId = session.threadId;
590→    }
591→    await this.sessionManager.patchRecord(session.id, {
592→      originalAgentSessionId: agentSessionId,
593→      platform: adoptPlatform,
594→    });
595→
596→    return {
597→      ok: true,
598→      sessionId: session.id,
599→      threadId: session.threadId,
600→      status: "adopted",
601→    };
602→  }
