 150→  async start(): Promise<void> {
 151→    this.bot = new Bot(this.telegramConfig.botToken, {
 152→      client: {
 153→        baseFetchConfig: { duplex: "half" } as RequestInit,
 154→        fetch: patchedFetch,
 155→      },
 156→    });
 157→    this.fileService = this.core.fileService;
 158→
 159→    // Initialize extracted managers
 160→    this.toolTracker = new TelegramToolCallTracker(
 161→      this.bot,
 162→      this.telegramConfig.chatId,
 163→      this.sendQueue,
 164→    );
 165→    this.draftManager = new DraftManager(
 166→      this.bot,
 167→      this.telegramConfig.chatId,
 168→      this.sendQueue,
 169→    );
 170→    this.skillManager = new SkillCommandManager(
 171→      this.bot,
 172→      this.telegramConfig.chatId,
 173→      this.sendQueue,
 174→      this.core.sessionManager,
 175→    );
 176→
 177→    // Global error handler — prevent unhandled errors from crashing the bot
 178→    this.bot.catch((err) => {
 179→      const rootCause = err.error instanceof Error ? err.error : err;
 180→      log.error({ err: rootCause }, "Telegram bot error");
 181→    });
 182→
 183→    // Auto-retry on 429 (Too Many Requests)
 184→    this.bot.api.config.use(async (prev, method, payload, signal) => {
 185→      const maxRetries = 3;
 186→      for (let attempt = 0; attempt <= maxRetries; attempt++) {
 187→        const result = await prev(method, payload, signal);
 188→        if (
 189→          result.ok ||
 190→          (result as { error_code?: number }).error_code !== 429 ||
 191→          attempt === maxRetries
 192→        ) {
 193→          return result;
 194→        }
 195→        const retryAfter =
 196→          ((result as { parameters?: { retry_after?: number } }).parameters
 197→            ?.retry_after ?? 5) + 1;
 198→        const rateLimitedMethods = [
 199→          "sendMessage",
 200→          "editMessageText",
 201→          "editMessageReplyMarkup",
 202→        ];
 203→        if (rateLimitedMethods.includes(method)) {
 204→          this.sendQueue.onRateLimited();
 205→        }
 206→        log.warn(
 207→          { method, retryAfter, attempt: attempt + 1 },
 208→          "Rate limited by Telegram, retrying",
 209→        );
 210→        await new Promise((r) => setTimeout(r, retryAfter * 1000));
 211→      }
 212→      return prev(method, payload, signal);
 213→    });
 214→
 215→    // Ensure allowed_updates includes callback_query on every poll
 216→    this.bot.api.config.use((prev, method, payload, signal) => {
 217→      if (method === "getUpdates") {
