 452→  private setupRoutes(): void {
 453→    this.bot.on("message:text", async (ctx) => {
 454→      const threadId = ctx.message.message_thread_id;
 455→      const text = ctx.message.text;
 456→
 457→      // Check for pending workspace input from interactive /new flow
 458→      if (
 459→        await handlePendingWorkspaceInput(
 460→          ctx,
 461→          this.core,
 462→          this.telegramConfig.chatId,
 463→          this.assistantTopicId,
 464→        )
 465→      ) {
 466→        return;
 467→      }
 468→
 469→      // Check for pending workspace input from interactive /resume flow
 470→      if (
 471→        await handlePendingResumeInput(
 472→          ctx,
 473→          this.core,
 474→          this.telegramConfig.chatId,
 475→          this.assistantTopicId,
 476→        )
 477→      ) {
 478→        return;
 479→      }
 480→
 481→      // General topic or no thread → redirect to assistant
 482→      if (!threadId) {
 483→        const html = redirectToAssistant(
 484→          this.telegramConfig.chatId,
 485→          this.assistantTopicId,
 486→        );
 487→        await ctx.reply(html, { parse_mode: "HTML" });
 488→        return;
 489→      }
 490→
 491→      // Notification topic → ignore
 492→      if (threadId === this.notificationTopicId) return;
 493→
 494→      // Strip leading "/" from unrecognized commands — registered commands
 495→      // (e.g. /new, /cancel) are already handled by bot.command() above.
 496→      // Unrecognized slash commands can cause agent subprocesses to hang.
 497→      const forwardText = text.startsWith("/") ? text.slice(1) : text;
 498→
 499→      // Assistant topic → forward to assistant session
 500→      if (threadId === this.assistantTopicId) {
 501→        if (!this.assistantSession) {
 502→          await ctx.reply(
 503→            "⚠️ Assistant is not available yet. Please try again shortly.",
 504→            { parse_mode: "HTML" },
 505→          );
 506→          return;
 507→        }
 508→        await this.draftManager.finalize(
 509→          this.assistantSession.id,
 510→          this.assistantSession.id,
 511→        );
 512→        ctx.replyWithChatAction("typing").catch(() => {});
 513→        handleAssistantMessage(this.assistantSession, forwardText).catch(
 514→          (err) => log.error({ err }, "Assistant error"),
 515→        );
 516→        return;
 517→      }
 518→
 519→      // Session topic → forward to core
 520→      const sessionId = this.core.sessionManager.getSessionByThread(
 521→        "telegram",
 522→        String(threadId),
 523→      )?.id;
 524→      if (sessionId)
 525→        await this.draftManager.finalize(sessionId, this.assistantSession?.id);
 526→      if (sessionId) {
 527→        const tracker = this.sessionTrackers.get(sessionId);
 528→        if (tracker) await tracker.onNewPrompt();
 529→      }
 530→      ctx.replyWithChatAction("typing").catch(() => {});
 531→      this.core
 532→        .handleMessage({
 533→          channelId: "telegram",
 534→          threadId: String(threadId),
 535→          userId: String(ctx.from.id),
 536→          text: forwardText,
 537→        })
 538→        .catch((err) => log.error({ err }, "handleMessage error"));
 539→    });
 540→
