 622→
 623→  async sendMessage(
 624→    sessionId: string,
 625→    content: OutgoingMessage,
 626→  ): Promise<void> {
 627→    // Suppress assistant messages during system prompt
 628→    if (this.assistantInitializing && sessionId === this.assistantSession?.id)
 629→      return;
 630→
 631→    const session = this.core.sessionManager.getSession(sessionId);
 632→    if (!session) return;
 633→
 634→    // Drop messages while topic is being recreated (archive in progress)
 635→    if (session.archiving) return;
 636→    const threadId = Number(session.threadId);
 637→    if (!threadId || isNaN(threadId)) {
 638→      log.warn(
 639→        { sessionId, threadId: session.threadId },
 640→        "Session has no valid threadId, skipping message",
 641→      );
 642→      return;
 643→    }
 644→
 645→    // Store threadId for handlers to use (keyed by sessionId for concurrency safety)
 646→    this._sessionThreadIds.set(sessionId, threadId);
 647→    try {
 648→      await super.sendMessage(sessionId, content);
 649→    } finally {
 650→      this._sessionThreadIds.delete(sessionId);
 651→    }
 652→  }
