 660→  protected async handleText(sessionId: string, content: OutgoingMessage): Promise<void> {
 661→    const threadId = this.getThreadId(sessionId);
 662→    // CRITICAL: This handler must be fully synchronous to preserve text ordering.
 663→    // sendMessage() is not awaited in wireSessionEvents, so multiple text events
 664→    // run concurrently. Any await here creates a gap where subsequent text events
 665→    // process first, causing out-of-order buffer accumulation.
 666→    if (!this.draftManager.hasDraft(sessionId)) {
 667→      const tracker = this.getOrCreateTracker(sessionId, threadId);
 668→      tracker.onTextStart().catch(() => {}); // Fire-and-forget, no await
 669→    }
 670→    const draft = this.draftManager.getOrCreate(sessionId, threadId);
 671→    draft.append(content.text);
 672→    this.draftManager.appendText(sessionId, content.text);
 673→  }
