 760→        ? chatIdStr.slice(4)
 761→        : chatIdStr.replace("-", "");
 762→      const usageMsgId = tracker.getUsageMsgId();
 763→      const deepLink = usageMsgId
 764→        ? `https://t.me/c/${numericId}/${threadId}/${usageMsgId}`
 765→        : `https://t.me/c/${numericId}/${threadId}`;
 766→      const text = `✅ <b>${escapeHtml(sessionName)}</b>\nTask completed.\n\n<a href="${deepLink}">→ Go to topic</a>`;
 767→      this.sendQueue
 768→        .enqueue(() =>
