 779→  protected async handleAttachment(sessionId: string, content: OutgoingMessage): Promise<void> {
 780→    const threadId = this.getThreadId(sessionId);
 781→    if (!content.attachment) return;
 782→    const { attachment } = content;
 783→
 784→    // Telegram bot API upload limit: 50MB
 785→    if (attachment.size > 50 * 1024 * 1024) {
 786→      log.warn(
 787→        {
 788→          sessionId,
 789→          fileName: attachment.fileName,
 790→          size: attachment.size,
 791→        },
 792→        "File too large for Telegram (>50MB)",
 793→      );
 794→      await this.sendQueue.enqueue(() =>
 795→        this.bot.api.sendMessage(
 796→          this.telegramConfig.chatId,
 797→          `⚠️ File too large to send (${Math.round(attachment.size / 1024 / 1024)}MB): ${escapeHtml(attachment.fileName)}`,
 798→          { message_thread_id: threadId, parse_mode: "HTML" },
 799→        ),
 800→      );
 801→      return;
 802→    }
 803→
 804→    try {
 805→      const inputFile = new InputFile(attachment.filePath);
 806→      if (attachment.type === "image") {
 807→        await this.sendQueue.enqueue(() =>
 808→          this.bot.api.sendPhoto(this.telegramConfig.chatId, inputFile, {
 809→            message_thread_id: threadId,
 810→          }),
 811→        );
 812→      } else if (attachment.type === "audio") {
 813→        await this.sendQueue.enqueue(() =>
 814→          this.bot.api.sendVoice(this.telegramConfig.chatId, inputFile, {
 815→            message_thread_id: threadId,
 816→          }),
 817→        );
 818→        // Strip [TTS]...[/TTS] block from the text message after voice is sent
 819→        const draft = this.draftManager.getDraft(sessionId);
 820→        if (draft) {
 821→          draft.stripPattern(/\[TTS\][\s\S]*?\[\/TTS\]/g).catch(() => {});
 822→        }
 823→      } else {
 824→        await this.sendQueue.enqueue(() =>
 825→          this.bot.api.sendDocument(this.telegramConfig.chatId, inputFile, {
 826→            message_thread_id: threadId,
 827→          }),
 828→        );
 829→      }
 830→    } catch (err) {
 831→      log.error(
 832→        { err, sessionId, fileName: attachment.fileName },
 833→        "Failed to send attachment",
 834→      );
 835→    }
 836→  }
