 919→  async sendNotification(notification: NotificationMessage): Promise<void> {
 920→    if (notification.sessionId === this.assistantSession?.id) return;
 921→
 922→    log.info(
 923→      { sessionId: notification.sessionId, type: notification.type },
 924→      "Notification sent",
 925→    );
 926→    if (!this.notificationTopicId) return;
 927→    const emoji: Record<string, string> = {
 928→      completed: "✅",
 929→      error: "❌",
 930→      permission: "🔐",
 931→      input_required: "💬",
 932→    };
 933→    let text = `${emoji[notification.type] || "ℹ️"} <b>${escapeHtml(notification.sessionName || "New session")}</b>\n`;
 934→    text += escapeHtml(notification.summary);
 935→
 936→    const deepLink =
 937→      notification.deepLink ??
 938→      (() => {
 939→        const session = this.core.sessionManager.getSession(
 940→          notification.sessionId,
 941→        );
 942→        const threadId = session?.threadId;
 943→        if (!threadId) return undefined;
 944→        const chatIdStr = String(this.telegramConfig.chatId);
