 946→          ? chatIdStr.slice(4)
 947→          : chatIdStr.replace("-", "");
 948→        return `https://t.me/c/${numericId}/${threadId}`;
 949→      })();
 950→
 951→    if (deepLink) {
 952→      text += `\n\n<a href="${deepLink}">→ Go to topic</a>`;
 953→    }
 954→
 955→    // Add Summary button for completed sessions
 956→    const replyMarkup =
 957→      notification.type === "completed"
 958→        ? {
 959→            inline_keyboard: [
 960→              [
 961→                {
 962→                  text: "📋 Summary",
 963→                  callback_data: `sm:summary:${notification.sessionId}`,
 964→                },
 965→              ],
 966→            ],
 967→          }
 968→        : undefined;
 969→
 970→    await this.sendQueue.enqueue(() =>
 971→      this.bot.api.sendMessage(this.telegramConfig.chatId, text, {
 972→        message_thread_id: this.notificationTopicId,
 973→        parse_mode: "HTML",
