1038→  private async downloadTelegramFile(
1039→    fileId: string,
1040→  ): Promise<{ buffer: Buffer; filePath: string } | null> {
1041→    try {
1042→      const file = await this.bot.api.getFile(fileId);
1043→      if (!file.file_path) return null;
1044→      const url = `https://api.telegram.org/file/bot${this.telegramConfig.botToken}/${file.file_path}`;
1045→      const response = await fetch(url);
1046→      if (!response.ok) return null;
1047→      const buffer = Buffer.from(await response.arrayBuffer());
1048→      return { buffer, filePath: file.file_path };
1049→    } catch (err) {
1050→      log.error({ err }, "Failed to download file from Telegram");
1051→      return null;
1052→    }
1053→  }
1054→
1055→  private async handleIncomingMedia(
1056→    threadId: number,
1057→    userId: number,
1058→    fileId: string,
1059→    fileName: string,
1060→    mimeType: string,
1061→    caption?: string,
1062→    convertOggToWav?: boolean,
1063→  ): Promise<void> {
1064→    const downloaded = await this.downloadTelegramFile(fileId);
1065→    if (!downloaded) return;
1066→
1067→    let buffer = downloaded.buffer;
1068→    let originalFilePath: string | undefined;
1069→    const sessionId = this.resolveSessionId(threadId) || "unknown";
1070→
1071→    if (convertOggToWav) {
1072→      // Save original OGG for STT (smaller, API-compatible)
1073→      const oggAtt = await this.fileService.saveFile(
1074→        sessionId,
1075→        "voice.ogg",
1076→        downloaded.buffer,
1077→        "audio/ogg",
1078→      );
1079→      originalFilePath = oggAtt.filePath;
1080→
1081→      try {
1082→        buffer = await this.fileService.convertOggToWav(buffer);
1083→      } catch (err) {
1084→        log.warn({ err }, "OGG→WAV conversion failed, saving original OGG");
1085→        fileName = "voice.ogg";
1086→        mimeType = "audio/ogg";
1087→        originalFilePath = undefined;
1088→      }
1089→    }
1090→
1091→    const att = await this.fileService.saveFile(
1092→      sessionId,
1093→      fileName,
1094→      buffer,
1095→      mimeType,
1096→    );
1097→    if (originalFilePath) {
1098→      att.originalFilePath = originalFilePath;
1099→    }
1100→
1101→    const rawText =
1102→      caption ||
1103→      `[${att.type === "image" ? "Photo" : att.type === "audio" ? "Audio" : "File"}: ${att.fileName}]`;
1104→    const text = rawText.startsWith("/") ? rawText.slice(1) : rawText;
1105→
1106→    // Assistant topic
1107→    if (threadId === this.assistantTopicId) {
1108→      if (this.assistantSession) {
1109→        await this.assistantSession.enqueuePrompt(text, [att]);
1110→      }
1111→      return;
1112→    }
1113→
1114→    // Session topic
1115→    const sid = this.resolveSessionId(threadId);
1116→    if (sid) await this.draftManager.finalize(sid, this.assistantSession?.id);
1117→    this.core
1118→      .handleMessage({
1119→        channelId: "telegram",
1120→        threadId: String(threadId),
1121→        userId: String(userId),
1122→        text,
1123→        attachments: [att],
1124→      })
1125→      .catch((err) => log.error({ err }, "handleMessage error"));
1126→  }
1127→
1128→  async cleanupSkillCommands(sessionId: string): Promise<void> {
1129→    await this.skillManager.cleanup(sessionId);
1130→  }
