1132→  async archiveSessionTopic(sessionId: string): Promise<void> {
1133→    const core = this.core as OpenACPCore;
1134→    const session = core.sessionManager.getSession(sessionId);
1135→    if (!session) return;
1136→
1137→    const chatId = this.telegramConfig.chatId;
1138→    const oldTopicId = Number(session.threadId);
1139→    // Strip existing 🔄 prefix to avoid stacking on repeated archives
1140→
1141→    // Set archiving flag — sendMessage will skip while this is true.
1142→    // Flag stays true until core finishes cancelSession (prevents race window).
1143→    session.archiving = true;
1144→
1145→    // Finalize any pending draft
1146→    await this.draftManager.finalize(session.id, this.assistantSession?.id);
1147→
1148→    // Cleanup all trackers
1149→    this.draftManager.cleanup(session.id);
1150→    this.toolTracker.cleanup(session.id);
1151→    await this.skillManager.cleanup(session.id);
1152→    const tracker = this.sessionTrackers.get(session.id);
1153→    if (tracker) {
1154→      tracker.destroy();
1155→      this.sessionTrackers.delete(session.id);
1156→    }
1157→
1158→    // Delete topic (removes all messages)
1159→    await deleteSessionTopic(this.bot, chatId, oldTopicId);
1160→  }
1161→}
