  1→import type { Session } from "./session.js";
  2→import type { IChannelAdapter } from "../channel.js";
  3→import type { MessageTransformer } from "../message-transformer.js";
  4→import type { NotificationManager } from "../../plugins/notifications/notification.js";
  5→import type { SessionManager } from "./session-manager.js";
  6→import type { AgentEvent, PermissionRequest, SessionStatus } from "../types.js";
  7→import type { EventBus } from "../event-bus.js";
  8→import { FileService } from "../../plugins/file-service/file-service.js";
  9→import type { MiddlewareChain } from "../plugin/middleware-chain.js";
 10→import { createChildLogger } from "../utils/log.js";
 11→
 12→const log = createChildLogger({ module: "session-bridge" });
 13→
 14→export interface BridgeDeps {
 15→  messageTransformer: MessageTransformer;
 16→  notificationManager: NotificationManager;
 17→  sessionManager: SessionManager;
 18→  eventBus?: EventBus;
 19→  fileService?: FileService;
 20→  middlewareChain?: MiddlewareChain;
 21→}
 22→
 23→export class SessionBridge {
 24→  private connected = false;
 25→  private agentEventHandler?: (event: AgentEvent) => void;
 26→  private sessionEventHandler?: (event: AgentEvent) => void;
 27→  private statusChangeHandler?: (
 28→    from: SessionStatus,
 29→    to: SessionStatus,
 30→  ) => void;
 31→  private namedHandler?: (name: string) => void;
 32→
 33→  constructor(
 34→    private session: Session,
 35→    private adapter: IChannelAdapter,
 36→    private deps: BridgeDeps,
 37→  ) {}
 38→
 39→  /** Send message to adapter, optionally running through message:outgoing middleware */
 40→  private async sendMessage(sessionId: string, message: ReturnType<MessageTransformer["transform"]>): Promise<void> {
 41→    const mw = this.deps.middlewareChain;
 42→    if (mw) {
 43→      const result = await mw.execute('message:outgoing', { sessionId, message }, async (m) => m);
 44→      if (!result) return; // blocked by middleware
 45→      this.adapter.sendMessage(sessionId, result.message);
 46→    } else {
 47→      this.adapter.sendMessage(sessionId, message);
 48→    }
 49→  }
 50→
 51→  connect(): void {
 52→    if (this.connected) return;
 53→    this.connected = true;
 54→
 55→    this.wireAgentToSession();
 56→    this.wireSessionToAdapter();
 57→    this.wirePermissions();
 58→    this.wireLifecycle();
 59→  }
 60→
 61→  disconnect(): void {
 62→    if (!this.connected) return;
 63→    this.connected = false;
 64→
 65→    if (this.agentEventHandler) {
 66→      this.session.agentInstance.off("agent_event", this.agentEventHandler);
 67→    }
 68→    if (this.sessionEventHandler) {
 69→      this.session.off("agent_event", this.sessionEventHandler);
 70→    }
 71→    if (this.statusChangeHandler) {
 72→      this.session.off("status_change", this.statusChangeHandler);
 73→    }
 74→    if (this.namedHandler) {
 75→      this.session.off("named", this.namedHandler);
 76→    }
 77→
 78→    // Reset agent callbacks to no-op
 79→    this.session.agentInstance.onPermissionRequest = async () => "";
 80→  }
 81→
 82→  private wireAgentToSession(): void {
 83→    this.agentEventHandler = (event: AgentEvent) => {
 84→      this.session.emit("agent_event", event);
 85→    };
 86→    this.session.agentInstance.on("agent_event", this.agentEventHandler);
 87→  }
 88→
 89→  private wireSessionToAdapter(): void {
 90→    this.sessionEventHandler = (event: AgentEvent) => {
 91→      // Hook: agent:beforeEvent — modifiable, can block
 92→      const mw = this.deps.middlewareChain;
 93→      if (mw) {
 94→        mw.execute('agent:beforeEvent', { sessionId: this.session.id, event }, async (e) => e).then((result) => {
 95→          if (!result) return; // blocked by middleware
 96→          const transformedEvent = result.event;
 97→          const outgoing = this.handleAgentEvent(transformedEvent);
 98→          // Hook: agent:afterEvent — read-only, fire-and-forget
 99→          mw.execute('agent:afterEvent', {
100→            sessionId: this.session.id,
101→            event: transformedEvent,
102→            outgoingMessage: outgoing ?? { type: 'text' as const, text: '' },
103→          }, async (e) => e).catch(() => {});
104→        }).catch(() => {
105→          // Middleware error — proceed with original event
106→          this.handleAgentEvent(event);
107→        });
108→      } else {
109→        this.handleAgentEvent(event);
110→      }
111→    };
112→
113→    this.session.on("agent_event", this.sessionEventHandler);
114→  }
115→
116→  private handleAgentEvent(event: AgentEvent): import('../types.js').OutgoingMessage | undefined {
117→    const session = this.session;
118→    const ctx = {
119→      get id() {
120→        return session.id;
121→      },
122→      get workingDirectory() {
123→        return session.workingDirectory;
124→      },
125→    };
126→
127→    let outgoing: import('../types.js').OutgoingMessage | undefined;
128→
129→      switch (event.type) {
130→        case "text":
131→        case "thought":
132→        case "tool_call":
133→        case "tool_update":
134→        case "plan":
135→        case "usage":
136→          outgoing = this.deps.messageTransformer.transform(event, ctx);
137→          this.sendMessage(this.session.id, outgoing);
138→          break;
139→
140→        case "session_end":
141→          this.session.finish(event.reason);
142→          this.adapter.cleanupSkillCommands?.(this.session.id);
143→          outgoing = this.deps.messageTransformer.transform(event);
144→          this.sendMessage(this.session.id, outgoing);
145→          this.deps.notificationManager.notify(this.session.channelId, {
146→            sessionId: this.session.id,
147→            sessionName: this.session.name,
148→            type: "completed",
149→            summary: `Session "${this.session.name || this.session.id}" completed\n⏱ ${Math.round((Date.now() - this.session.createdAt.getTime()) / 60000)} min · 💬 ${this.session.promptCount} prompts`,
150→          });
151→          break;
152→
153→        case "error":
154→          this.session.fail(event.message);
155→          this.adapter.cleanupSkillCommands?.(this.session.id);
156→          outgoing = this.deps.messageTransformer.transform(event);
157→          this.sendMessage(this.session.id, outgoing);
158→          this.deps.notificationManager.notify(this.session.channelId, {
159→            sessionId: this.session.id,
160→            sessionName: this.session.name,
161→            type: "error",
162→            summary: event.message,
163→          });
164→          break;
165→
166→        case "image_content": {
167→          if (this.deps.fileService) {
168→            const fs = this.deps.fileService;
169→            const sid = this.session.id;
170→            const { data, mimeType } = event;
171→            const buffer = Buffer.from(data, "base64");
172→            const ext = FileService.extensionFromMime(mimeType);
173→            fs.saveFile(sid, `agent-image${ext}`, buffer, mimeType)
174→              .then((att) => {
175→                this.sendMessage(sid, {
176→                  type: "attachment",
177→                  text: "",
178→                  attachment: att,
179→                });
180→              })
181→              .catch((err) => log.error({ err }, "Failed to save agent image"));
182→          }
183→          break;
184→        }
185→        case "audio_content": {
186→          if (this.deps.fileService) {
187→            const fs = this.deps.fileService;
188→            const sid = this.session.id;
189→            const { data, mimeType } = event;
190→            const buffer = Buffer.from(data, "base64");
191→            const ext = FileService.extensionFromMime(mimeType);
192→            fs.saveFile(sid, `agent-audio${ext}`, buffer, mimeType)
193→              .then((att) => {
194→                this.sendMessage(sid, {
195→                  type: "attachment",
196→                  text: "",
197→                  attachment: att,
198→                });
199→              })
200→              .catch((err) => log.error({ err }, "Failed to save agent audio"));
201→          }
202→          break;
203→        }
204→
205→        case "commands_update":
206→          log.debug({ commands: event.commands }, "Commands available");
207→          this.adapter.sendSkillCommands?.(this.session.id, event.commands);
208→          break;
209→
210→        case "system_message":
211→          outgoing = this.deps.messageTransformer.transform(event);
212→          this.sendMessage(this.session.id, outgoing);
213→          break;
214→
215→        case "session_info_update":
216→          if (event.title) {
217→            this.session.setName(event.title);
218→          }
219→          outgoing = this.deps.messageTransformer.transform(event);
220→          this.sendMessage(this.session.id, outgoing);
221→          break;
222→
223→        case "current_mode_update":
224→          this.session.updateMode(event.modeId);
225→          outgoing = this.deps.messageTransformer.transform(event);
226→          this.sendMessage(this.session.id, outgoing);
227→          break;
228→
229→        case "config_option_update":
230→          this.session.updateConfigOptions(event.options);
231→          outgoing = this.deps.messageTransformer.transform(event);
232→          this.sendMessage(this.session.id, outgoing);
233→          break;
234→
235→        case "model_update":
236→          this.session.updateModel(event.modelId);
237→          outgoing = this.deps.messageTransformer.transform(event);
238→          this.sendMessage(this.session.id, outgoing);
239→          break;
240→
241→        case "user_message_chunk":
242→          outgoing = this.deps.messageTransformer.transform(event);
243→          this.sendMessage(this.session.id, outgoing);
244→          break;
245→
246→        case "resource_content":
247→        case "resource_link":
248→          outgoing = this.deps.messageTransformer.transform(event);
249→          this.sendMessage(this.session.id, outgoing);
250→          break;
251→      }
252→
253→      this.deps.eventBus?.emit("agent:event", {
254→        sessionId: this.session.id,
255→        event,
256→      });
257→
258→    return outgoing;
259→  }
260→
261→  private wirePermissions(): void {
262→    const mw = this.deps.middlewareChain;
263→
264→    this.session.agentInstance.onPermissionRequest = async (
265→      request: PermissionRequest,
266→    ) => {
267→      const startTime = Date.now();
268→
269→      // Hook: permission:beforeRequest — modifiable, can block or autoResolve
270→      let permReq = request;
271→      if (mw) {
272→        const payload = { sessionId: this.session.id, request, autoResolve: undefined as string | undefined };
273→        const result = await mw.execute('permission:beforeRequest', payload, async (r) => r);
274→        if (!result) return ""; // blocked by middleware
275→        permReq = result.request;
276→        // I4: If middleware set autoResolve, skip UI and return directly
277→        if (result.autoResolve) {
278→          if (mw) {
279→            mw.execute('permission:afterResolve', {
280→              sessionId: this.session.id, requestId: permReq.id, decision: result.autoResolve, userId: 'middleware', durationMs: Date.now() - startTime,
281→            }, async (p) => p).catch(() => {});
282→          }
283→          return result.autoResolve;
284→        }
285→      }
286→
287→      this.session.emit("permission_request", permReq);
288→      this.deps.eventBus?.emit("permission:request", {
289→        sessionId: this.session.id,
290→        permission: permReq,
291→      });
292→
293→      // Auto-approve openacp CLI commands
294→      if (permReq.description.toLowerCase().includes("openacp")) {
295→        const allowOption = permReq.options.find((o) => o.isAllow);
296→        if (allowOption) {
297→          log.info(
298→            { sessionId: this.session.id, requestId: permReq.id },
299→            "Auto-approving openacp command",
300→          );
301→          // Hook: permission:afterResolve — read-only, fire-and-forget
302→          if (mw) {
303→            mw.execute('permission:afterResolve', {
304→              sessionId: this.session.id, requestId: permReq.id, decision: allowOption.id, userId: 'system', durationMs: Date.now() - startTime,
305→            }, async (p) => p).catch(() => {});
306→          }
307→          return allowOption.id;
308→        }
309→      }
310→
311→      // Dangerous mode: auto-approve all permissions
312→      if (this.session.dangerousMode) {
313→        const allowOption = permReq.options.find((o) => o.isAllow);
314→        if (allowOption) {
315→          log.info(
316→            { sessionId: this.session.id, requestId: permReq.id, optionId: allowOption.id },
317→            "Dangerous mode: auto-approving permission",
318→          );
319→          // Hook: permission:afterResolve — read-only, fire-and-forget
320→          if (mw) {
321→            mw.execute('permission:afterResolve', {
322→              sessionId: this.session.id, requestId: permReq.id, decision: allowOption.id, userId: 'system', durationMs: Date.now() - startTime,
323→            }, async (p) => p).catch(() => {});
324→          }
325→          return allowOption.id;
326→        }
327→      }
328→
329→      // Set pending BEFORE sending UI to avoid race condition
330→      const promise = this.session.permissionGate.setPending(permReq);
331→
332→      // Send permission UI to session topic
333→      await this.adapter.sendPermissionRequest(this.session.id, permReq);
334→
335→      // Wait for user response — adapter resolves this promise
336→      const optionId = await promise;
337→
338→      // Hook: permission:afterResolve — read-only, fire-and-forget
339→      if (mw) {
340→        mw.execute('permission:afterResolve', {
341→          sessionId: this.session.id, requestId: permReq.id, decision: optionId, userId: 'user', durationMs: Date.now() - startTime,
342→        }, async (p) => p).catch(() => {});
343→      }
344→
345→      return optionId;
346→    };
347→  }
348→
349→  private wireLifecycle(): void {
350→    // Persist status changes and auto-disconnect on terminal states
351→    this.statusChangeHandler = (from: SessionStatus, to: SessionStatus) => {
352→      this.deps.sessionManager.patchRecord(this.session.id, {
353→        status: to,
354→        lastActiveAt: new Date().toISOString(),
355→      });
356→      this.deps.eventBus?.emit("session:updated", {
357→        sessionId: this.session.id,
358→        status: to,
359→      });
360→
361→      // Auto-disconnect on terminal states
362→      if (to === "finished" || to === "cancelled") {
363→        // Disconnect on next tick so current event handlers can complete
364→        queueMicrotask(() => this.disconnect());
365→      }
366→    };
367→    this.session.on("status_change", this.statusChangeHandler);
368→
369→    // Persist and relay name changes
370→    this.namedHandler = (name: string) => {
371→      this.deps.sessionManager.patchRecord(this.session.id, { name });
372→      this.deps.eventBus?.emit("session:updated", {
373→        sessionId: this.session.id,
374→        name,
375→      });
376→      this.adapter.renameSessionThread(this.session.id, name);
377→    };
378→    this.session.on("named", this.namedHandler);
379→  }
380→}
