  1→import { nanoid } from "nanoid";
  2→import type { AgentManager } from "../agents/agent-manager.js";
  3→import type { SessionManager } from "./session-manager.js";
  4→import type { SpeechService } from "../../plugins/speech/exports.js";
  5→import type { EventBus } from "../event-bus.js";
  6→import type { UsageStore } from "../../plugins/usage/usage-store.js";
  7→import type { UsageBudget } from "../../plugins/usage/usage-budget.js";
  8→import type { NotificationManager } from "../../plugins/notifications/notification.js";
  9→import type { TunnelService } from "../../plugins/tunnel/tunnel-service.js";
 10→import type { AgentEvent, UsageRecord } from "../types.js";
 11→import type { MiddlewareChain } from "../plugin/middleware-chain.js";
 12→import { Session } from "./session.js";
 13→import { createChildLogger } from "../utils/log.js";
 14→
 15→const log = createChildLogger({ module: "session-factory" });
 16→
 17→export interface SessionCreateParams {
 18→  channelId: string;
 19→  agentName: string;
 20→  workingDirectory: string;
 21→  resumeAgentSessionId?: string;
 22→  existingSessionId?: string;
 23→  initialName?: string;
 24→}
 25→
 26→export interface SideEffectDeps {
 27→  usageStore?: UsageStore | null;
 28→  usageBudget?: UsageBudget | null;
 29→  notificationManager: NotificationManager;
 30→  tunnelService?: TunnelService;
 31→}
 32→
 33→export class SessionFactory {
 34→  middlewareChain?: MiddlewareChain;
 35→
 36→  constructor(
 37→    private agentManager: AgentManager,
 38→    private sessionManager: SessionManager,
 39→    private speechServiceAccessor: SpeechService | (() => SpeechService),
 40→    private eventBus: EventBus,
 41→  ) {}
 42→
 43→  private get speechService(): SpeechService {
 44→    return typeof this.speechServiceAccessor === 'function'
 45→      ? this.speechServiceAccessor()
 46→      : this.speechServiceAccessor;
 47→  }
 48→
 49→  async create(params: SessionCreateParams): Promise<Session> {
 50→    // Hook: session:beforeCreate — modifiable, can block
 51→    let createParams = params;
 52→    if (this.middlewareChain) {
 53→      const payload = {
 54→        agentName: params.agentName,
 55→        workingDir: params.workingDirectory,
 56→        userId: '', // userId is not part of SessionCreateParams — resolved upstream
 57→        channelId: params.channelId,
 58→        threadId: '', // threadId is assigned after session creation
 59→      };
 60→      const result = await this.middlewareChain.execute('session:beforeCreate', payload, async (p) => p);
 61→      if (!result) throw new Error("Session creation blocked by middleware");
 62→      // Apply any middleware modifications back to create params
 63→      createParams = {
 64→        ...params,
 65→        agentName: result.agentName,
 66→        workingDirectory: result.workingDir,
 67→        channelId: result.channelId,
 68→      };
 69→    }
 70→
 71→    // 1. Spawn or resume agent
 72→    const agentInstance = createParams.resumeAgentSessionId
 73→      ? await this.agentManager.resume(
 74→          createParams.agentName,
 75→          createParams.workingDirectory,
 76→          createParams.resumeAgentSessionId,
 77→        )
 78→      : await this.agentManager.spawn(
 79→          createParams.agentName,
 80→          createParams.workingDirectory,
 81→        );
 82→
 83→    // Wire middleware chain to agent instance for FS/terminal hooks
 84→    agentInstance.middlewareChain = this.middlewareChain;
 85→
 86→    // 2. Create Session instance
 87→    const session = new Session({
 88→      id: createParams.existingSessionId,
 89→      channelId: createParams.channelId,
 90→      agentName: createParams.agentName,
 91→      workingDirectory: createParams.workingDirectory,
 92→      agentInstance,
 93→      speechService: this.speechService,
 94→    });
 95→    session.agentSessionId = agentInstance.sessionId;
 96→    session.middlewareChain = this.middlewareChain;
 97→    if (createParams.initialName) {
 98→      session.name = createParams.initialName;
 99→    }
100→
101→    // 3. Register in SessionManager
102→    this.sessionManager.registerSession(session);
103→    this.eventBus.emit("session:created", {
104→      sessionId: session.id,
105→      agent: session.agentName,
106→      status: session.status,
107→    });
108→
109→    return session;
110→  }
111→
112→  wireSideEffects(session: Session, deps: SideEffectDeps): void {
113→    // Wire usage tracking
114→    if (deps.usageStore) {
115→      const usageStore = deps.usageStore;
116→      const usageBudget = deps.usageBudget;
117→      const notificationManager = deps.notificationManager;
118→
119→      session.on("agent_event", (event: AgentEvent) => {
120→        if (event.type !== "usage") return;
121→        const record: UsageRecord = {
122→          id: nanoid(),
123→          sessionId: session.id,
124→          agentName: session.agentName,
125→          tokensUsed: event.tokensUsed ?? 0,
126→          contextSize: event.contextSize ?? 0,
127→          cost: event.cost,
128→          timestamp: new Date().toISOString(),
129→        };
130→        usageStore.append(record);
131→
132→        if (usageBudget) {
133→          const result = usageBudget.check();
134→          if (result.message) {
135→            notificationManager.notifyAll({
136→              sessionId: session.id,
137→              sessionName: session.name,
138→              type: "budget_warning",
139→              summary: result.message,
140→            });
141→          }
142→        }
143→      });
144→    }
145→
146→    // Clean up user tunnels when session ends
147→    session.on("status_change", (_from, to) => {
148→      if ((to === "finished" || to === "cancelled") && deps.tunnelService) {
149→        deps.tunnelService
150→          .stopBySession(session.id)
151→          .then((stopped) => {
152→            for (const entry of stopped) {
153→              deps.notificationManager
154→                .notifyAll({
155→                  sessionId: session.id,
156→                  sessionName: session.name,
157→                  type: "completed",
158→                  summary: `Tunnel stopped: port ${entry.port}${entry.label ? ` (${entry.label})` : ""} — session ended`,
159→                })
160→                .catch(() => {});
161→            }
162→          })
163→          .catch(() => {});
164→      }
165→    });
166→  }
167→}
