 3→
 4→export function registerTopicRoutes(router: Router, deps: RouteDeps): void {
 5→  router.get("/api/topics", async (req, res) => {
 6→    if (!deps.topicManager) {
 7→      deps.sendJson(res, 501, { error: "Topic management not available" });
 8→      return;
 9→    }
10→    const url = req.url || "";
11→    const params = new URL(url, "http://localhost").searchParams;
12→    const statusParam = params.get("status");
13→    const filter = statusParam
14→      ? { statuses: statusParam.split(",") }
15→      : undefined;
16→    const topics = deps.topicManager.listTopics(filter);
17→    deps.sendJson(res, 200, { topics });
18→  });
19→
20→  router.post("/api/topics/cleanup", async (req, res) => {
21→    if (!deps.topicManager) {
22→      deps.sendJson(res, 501, { error: "Topic management not available" });
23→      return;
24→    }
25→    const body = await deps.readBody(req);
26→    let statuses: string[] | undefined;
27→    if (body) {
28→      try {
29→        statuses = JSON.parse(body).statuses;
30→      } catch {
31→        /* use defaults */
32→      }
33→    }
34→    const result = await deps.topicManager.cleanup(statuses);
35→    deps.sendJson(res, 200, result);
36→  });
37→
38→  router.delete("/api/topics/:sessionId", async (req, res, params) => {
39→    if (!deps.topicManager) {
40→      deps.sendJson(res, 501, { error: "Topic management not available" });
41→      return;
42→    }
43→    const sessionId = decodeURIComponent(params.sessionId);
44→    const url = req.url || "";
45→    const urlParams = new URL(url, "http://localhost").searchParams;
46→    const force = urlParams.get("force") === "true";
47→    const result = await deps.topicManager.deleteTopic(
48→      sessionId,
49→      force ? { confirmed: true } : undefined,
50→    );
51→    if (result.ok) {
52→      deps.sendJson(res, 200, result);
53→    } else if (result.needsConfirmation) {
54→      deps.sendJson(res, 409, {
55→        error: "Session is active",
56→        needsConfirmation: true,
57→        session: result.session,
58→      });
59→    } else if (result.error === "Cannot delete system topic") {
60→      deps.sendJson(res, 403, { error: result.error });
61→    } else {
62→      deps.sendJson(res, 404, { error: result.error ?? "Not found" });
63→    }
64→  });
65→}
