377→  // --- Unified Session Creation Pipeline ---
378→
379→  async createSession(params: {
380→    channelId: string;
381→    agentName: string;
382→    workingDirectory: string;
383→    resumeAgentSessionId?: string;
384→    existingSessionId?: string;
385→    createThread?: boolean;
386→    initialName?: string;
387→  }): Promise<Session> {
388→    // 1-3. Spawn/resume agent, create Session, register in SessionManager
389→    const session = await this.sessionFactory.create(params);
390→
391→    // 4. Create thread if needed
392→    const adapter = this.adapters.get(params.channelId);
393→    if (params.createThread && adapter) {
394→      const threadId = await adapter.createSessionThread(
395→        session.id,
396→        params.initialName ?? `🔄 ${params.agentName} — New Session`,
397→      );
398→      session.threadId = threadId;
399→    }
400→
401→    // 5. Connect SessionBridge
402→    if (adapter) {
403→      const bridge = this.createBridge(session, adapter);
404→      bridge.connect();
405→    }
406→
407→    // 5b-5c. Wire usage tracking and tunnel cleanup
408→    this.sessionFactory.wireSideEffects(session, {
409→      usageStore: this.usageStore,
410→      usageBudget: this.usageBudget,
411→      notificationManager: this.notificationManager,
412→      tunnelService: this._tunnelService,
413→    });
414→
415→    // 6. Persist initial record
416→    // Preserve existing platform data (e.g. topicId) when resuming an existing session
417→    const existingRecord = this.sessionStore?.get(session.id);
418→    const platform: Record<string, unknown> = {
419→      ...(existingRecord?.platform ?? {}),
420→    };
421→    if (session.threadId) {
422→      if (params.channelId === "telegram") {
423→        platform.topicId = Number(session.threadId);
424→      } else {
425→        platform.threadId = session.threadId;
426→      }
427→    }
428→    await this.sessionManager.patchRecord(session.id, {
429→      sessionId: session.id,
430→      agentSessionId: session.agentSessionId,
431→      agentName: params.agentName,
432→      workingDir: params.workingDirectory,
433→      channelId: params.channelId,
434→      status: session.status,
435→      createdAt: session.createdAt.toISOString(),
436→      lastActiveAt: new Date().toISOString(),
437→      name: session.name,
438→      platform,
439→    });
440→
441→    log.info(
442→      { sessionId: session.id, agentName: params.agentName },
443→      "Session created via pipeline",
444→    );
445→    return session;
446→  }
