604→  async handleNewChat(
605→    channelId: string,
606→    currentThreadId: string,
607→  ): Promise<Session | null> {
608→    const currentSession = this.sessionManager.getSessionByThread(
609→      channelId,
610→      currentThreadId,
611→    );
612→
613→    if (currentSession) {
614→      return this.handleNewSession(
615→        channelId,
616→        currentSession.agentName,
617→        currentSession.workingDirectory,
618→      );
619→    }
620→
621→    // Fallback: look up from store (e.g. after restart before lazy resume)
622→    const record = this.sessionManager.getRecordByThread(
623→      channelId,
624→      currentThreadId,
625→    );
626→    if (!record || record.status === "cancelled" || record.status === "error")
627→      return null;
628→
629→    return this.handleNewSession(
630→      channelId,
631→      record.agentName,
632→      record.workingDir,
633→    );
