668→  // --- Lazy Resume ---
669→
670→  /**
671→   * Get active session by thread, or attempt lazy resume from store.
672→   * Used by adapter command handlers that need a session but don't go through handleMessage().
673→   */
674→  async getOrResumeSession(channelId: string, threadId: string): Promise<Session | null> {
675→    const session = this.sessionManager.getSessionByThread(channelId, threadId);
676→    if (session) return session;
677→    return this.lazyResume({ channelId, threadId, userId: "", text: "" });
678→  }
679→
680→  private async lazyResume(message: IncomingMessage): Promise<Session | null> {
681→    const store = this.sessionStore;
682→    if (!store) return null;
683→
684→    const lockKey = `${message.channelId}:${message.threadId}`;
685→
686→    // Check for existing resume in progress
687→    const existing = this.resumeLocks.get(lockKey);
688→    if (existing) return existing;
689→
690→    const record = store.findByPlatform(
691→      message.channelId,
692→      (p) => String(p.topicId) === message.threadId,
693→    );
694→    if (!record) {
695→      log.debug(
696→        { threadId: message.threadId, channelId: message.channelId },
697→        "No session record found for thread",
698→      );
699→      return null;
700→    }
701→
702→    // Don't resume errored sessions (cancelled sessions can still be resumed)
703→    if (record.status === "error") {
704→      log.debug(
705→        {
706→          threadId: message.threadId,
707→          sessionId: record.sessionId,
708→          status: record.status,
709→        },
710→        "Skipping resume of error session",
711→      );
712→      return null;
713→    }
714→
715→    log.info(
716→      {
717→        threadId: message.threadId,
718→        sessionId: record.sessionId,
719→        status: record.status,
720→      },
721→      "Lazy resume: found record, attempting resume",
722→    );
723→
724→    const resumePromise = (async (): Promise<Session | null> => {
725→      try {
726→        const session = await this.createSession({
727→          channelId: record.channelId,
728→          agentName: record.agentName,
729→          workingDirectory: record.workingDir,
730→          resumeAgentSessionId: record.agentSessionId,
731→          existingSessionId: record.sessionId,
732→          initialName: record.name,
733→        });
734→        session.threadId = message.threadId;
735→        session.activate();
736→        session.dangerousMode = record.dangerousMode ?? false;
737→
738→        log.info(
739→          { sessionId: session.id, threadId: message.threadId },
740→          "Lazy resume successful",
741→        );
742→        return session;
743→      } catch (err) {
744→        log.error({ err, record }, "Lazy resume failed");
745→        // Send error feedback to user instead of silent drop
746→        const adapter = this.adapters.get(message.channelId);
747→        if (adapter) {
748→          try {
749→            await adapter.sendMessage(message.threadId, {
750→              type: "error",
751→              text: `⚠️ Failed to resume session: ${err instanceof Error ? err.message : String(err)}`,
752→            });
753→          } catch {
754→            /* best effort */
755→          }
756→        }
757→        return null;
758→      } finally {
759→        this.resumeLocks.delete(lockKey);
760→      }
761→    })();
762→
763→    this.resumeLocks.set(lockKey, resumePromise);
764→    return resumePromise;
765→  }
766→
767→  // --- Event Wiring ---
768→
769→  /** Create a SessionBridge for the given session and adapter */
770→  createBridge(session: Session, adapter: IChannelAdapter): SessionBridge {
771→    return new SessionBridge(session, adapter, {
772→      messageTransformer: this.messageTransformer,
773→      notificationManager: this.notificationManager,
774→      sessionManager: this.sessionManager,
775→      eventBus: this.eventBus,
776→      fileService: this.fileService,
777→      middlewareChain: this.lifecycleManager?.middlewareChain,
778→    });
779→  }
780→}
