  1→import type { AgentManager } from "../agents/agent-manager.js";
  2→import { Session } from "./session.js";
  3→import type { SessionStore } from "./session-store.js";
  4→import type { EventBus } from "../event-bus.js";
  5→import type { MiddlewareChain } from "../plugin/middleware-chain.js";
  6→
  7→export class SessionManager {
  8→  private sessions: Map<string, Session> = new Map();
  9→  private store: SessionStore | null;
 10→  private eventBus?: EventBus;
 11→  middlewareChain?: MiddlewareChain;
 12→
 13→  setEventBus(eventBus: EventBus): void {
 14→    this.eventBus = eventBus;
 15→  }
 16→
 17→  constructor(store: SessionStore | null = null) {
 18→    this.store = store;
 19→  }
 20→
 21→  async createSession(
 22→    channelId: string,
 23→    agentName: string,
 24→    workingDirectory: string,
 25→    agentManager: AgentManager,
 26→  ): Promise<Session> {
 27→    const agentInstance = await agentManager.spawn(agentName, workingDirectory);
 28→    const session = new Session({
 29→      channelId,
 30→      agentName,
 31→      workingDirectory,
 32→      agentInstance,
 33→    });
 34→    this.sessions.set(session.id, session);
 35→    session.agentSessionId = session.agentInstance.sessionId;
 36→
 37→    if (this.store) {
 38→      await this.store.save({
 39→        sessionId: session.id,
 40→        agentSessionId: session.agentInstance.sessionId,
 41→        agentName: session.agentName,
 42→        workingDir: session.workingDirectory,
 43→        channelId,
 44→        status: session.status,
 45→        createdAt: session.createdAt.toISOString(),
 46→        lastActiveAt: new Date().toISOString(),
 47→        name: session.name,
 48→        dangerousMode: false,
 49→        platform: {},
 50→      });
 51→    }
 52→
 53→    return session;
 54→  }
 55→
 56→  getSession(sessionId: string): Session | undefined {
 57→    return this.sessions.get(sessionId);
 58→  }
 59→
 60→  getSessionByThread(channelId: string, threadId: string): Session | undefined {
 61→    for (const session of this.sessions.values()) {
 62→      if (session.channelId === channelId && session.threadId === threadId) {
 63→        return session;
 64→      }
 65→    }
 66→    return undefined;
 67→  }
 68→
 69→  getSessionByAgentSessionId(agentSessionId: string): Session | undefined {
 70→    for (const session of this.sessions.values()) {
 71→      if (session.agentSessionId === agentSessionId) {
 72→        return session;
 73→      }
 74→    }
 75→    return undefined;
 76→  }
 77→
 78→  getRecordByAgentSessionId(
 79→    agentSessionId: string,
 80→  ): import("../types.js").SessionRecord | undefined {
 81→    return this.store?.findByAgentSessionId(agentSessionId);
 82→  }
 83→
 84→  getRecordByThread(
 85→    channelId: string,
 86→    threadId: string,
 87→  ): import("../types.js").SessionRecord | undefined {
 88→    return this.store?.findByPlatform(
 89→      channelId,
 90→      (p) => String(p.topicId) === threadId || p.threadId === threadId,
 91→    );
 92→  }
 93→
 94→  registerSession(session: Session): void {
 95→    this.sessions.set(session.id, session);
 96→  }
 97→
 98→  async patchRecord(
 99→    sessionId: string,
100→    patch: Partial<import("../types.js").SessionRecord>,
101→  ): Promise<void> {
102→    if (!this.store) return;
103→    const record = this.store.get(sessionId);
104→    if (record) {
105→      await this.store.save({ ...record, ...patch });
106→    } else if (patch.sessionId) {
107→      // Initial save — treat patch as full record
108→      await this.store.save(patch as import("../types.js").SessionRecord);
109→    }
110→  }
111→
112→  getSessionRecord(
113→    sessionId: string,
114→  ): import("../types.js").SessionRecord | undefined {
115→    return this.store?.get(sessionId);
116→  }
117→
118→  async cancelSession(sessionId: string): Promise<void> {
119→    const session = this.sessions.get(sessionId);
120→    if (session) {
121→      await session.abortPrompt();
122→      session.markCancelled();
123→    }
124→    if (this.store) {
125→      const record = this.store.get(sessionId);
126→      if (record && record.status !== "cancelled") {
127→        await this.store.save({ ...record, status: "cancelled" });
128→      }
129→    }
130→    // Hook: session:afterDestroy — read-only, fire-and-forget
131→    if (this.middlewareChain) {
132→      this.middlewareChain.execute('session:afterDestroy', { sessionId }, async (p) => p).catch(() => {});
133→    }
134→  }
135→
136→  listSessions(channelId?: string): Session[] {
137→    const all = Array.from(this.sessions.values());
138→    if (channelId) return all.filter((s) => s.channelId === channelId);
139→    return all;
140→  }
141→
142→  listRecords(filter?: {
143→    statuses?: string[];
144→  }): import("../types.js").SessionRecord[] {
145→    if (!this.store) return [];
146→    let records = this.store.list();
147→    if (filter?.statuses?.length) {
148→      records = records.filter((r) => filter.statuses!.includes(r.status));
149→    }
150→    return records;
151→  }
152→
153→  async removeRecord(sessionId: string): Promise<void> {
154→    if (!this.store) return;
155→    await this.store.remove(sessionId);
156→    this.eventBus?.emit("session:deleted", { sessionId });
157→  }
158→
159→  async destroyAll(): Promise<void> {
160→    if (this.store) {
161→      for (const session of this.sessions.values()) {
162→        const record = this.store.get(session.id);
163→        if (record) {
164→          await this.store.save({ ...record, status: "finished" });
165→        }
166→      }
167→    }
168→    const sessionIds = [...this.sessions.keys()];
169→    for (const session of this.sessions.values()) {
170→      await session.destroy();
171→    }
172→    this.sessions.clear();
173→    // Hook: session:afterDestroy — read-only, fire-and-forget
174→    if (this.middlewareChain) {
175→      for (const sessionId of sessionIds) {
176→        this.middlewareChain.execute('session:afterDestroy', { sessionId }, async (p) => p).catch(() => {});
177→      }
178→    }
179→  }
180→}
