  64→/**
  65→ * Wraps native fetch to work around grammY's polyfilled AbortController.
  66→ * grammY uses abort-controller polyfill whose AbortSignal fails instanceof
  67→ * checks in Node 24+ native fetch. This wrapper re-creates a native
  68→ * AbortSignal from the polyfilled one before passing it to fetch.
  69→ */
  70→function patchedFetch(
  71→  input: RequestInfo | URL,
  72→  init?: RequestInit,
  73→): Promise<Response> {
  74→  if (init?.signal && !(init.signal instanceof AbortSignal)) {
  75→    const nativeController = new AbortController();
  76→    const polyfillSignal = init.signal as unknown as {
  77→      aborted: boolean;
  78→      addEventListener: (event: string, fn: () => void) => void;
  79→    };
  80→    if (polyfillSignal.aborted) {
  81→      nativeController.abort();
  82→    } else {
  83→      polyfillSignal.addEventListener("abort", () => nativeController.abort());
  84→    }
  85→    init = { ...init, signal: nativeController.signal };
  86→  }
  87→  return fetch(input, init);
  88→}
