 142→    super(
 143→      { configManager: core.configManager },
 144→      { ...config as Record<string, unknown>, maxMessageLength: 4096, enabled: config.enabled ?? true } as MessagingAdapterConfig,
 145→    );
 146→    this.core = core;
 147→    this.telegramConfig = config;
