 194→        }
 195→        const retryAfter =
 196→          ((result as { parameters?: { retry_after?: number } }).parameters
 197→            ?.retry_after ?? 5) + 1;
 198→        const rateLimitedMethods = [
 199→          "sendMessage",
 200→          "editMessageText",
 201→          "editMessageReplyMarkup",
 202→        ];
 203→        if (rateLimitedMethods.includes(method)) {
 204→          this.sendQueue.onRateLimited();
 205→        }
 206→        log.warn(
 207→          { method, retryAfter, attempt: attempt + 1 },
 208→          "Rate limited by Telegram, retrying",
 209→        );
 210→        await new Promise((r) => setTimeout(r, retryAfter * 1000));
 211→      }
 212→      return prev(method, payload, signal);
 213→    });
 214→
 215→    // Ensure allowed_updates includes callback_query on every poll
 216→    this.bot.api.config.use((prev, method, payload, signal) => {
 217→      if (method === "getUpdates") {
 218→        const p = payload as Record<string, unknown>;
 219→        p.allowed_updates = (p.allowed_updates as string[] | undefined) ?? [
 220→          "message",
 221→          "callback_query",
 222→        ];
 223→      }
 224→      return prev(method, payload, signal);
 225→    });
 226→
 227→    // Register static commands for Telegram autocomplete
 228→    await this.bot.api.setMyCommands(STATIC_COMMANDS, {
 229→      scope: { type: "chat", chat_id: this.telegramConfig.chatId },
 230→    });
 231→
 232→    // Middleware: only accept updates from configured chatId
 233→    this.bot.use((ctx, next) => {
 234→      const chatId = ctx.chat?.id ?? ctx.callbackQuery?.message?.chat?.id;
 235→      if (chatId !== this.telegramConfig.chatId) return;
 236→      return next();
 237→    });
 238→
 239→    // Ensure system topics exist
 240→    const topics = await ensureTopics(
 241→      this.bot,
 242→      this.telegramConfig.chatId,
 243→      this.telegramConfig,
 244→      async (updates) => {
 245→        await this.core.configManager.save({
 246→          channels: { telegram: updates },
 247→        });
 248→      },
 249→    );
 250→    this.notificationTopicId = topics.notificationTopicId;
 251→    this.assistantTopicId = topics.assistantTopicId;
 252→
 253→    // Setup permission handler
 254→    this.permissionHandler = new PermissionHandler(
 255→      this.bot,
 256→      this.telegramConfig.chatId,
 257→      (sessionId) => this.core.sessionManager.getSession(sessionId),
 258→      (notification) => this.sendNotification(notification),
 259→    );
 260→
 261→    // Callback registration order matters!
 262→    setupDangerousModeCallbacks(this.bot, this.core as OpenACPCore);
 263→    setupTTSCallbacks(this.bot, this.core as OpenACPCore);
 264→    setupVerbosityCallbacks(this.bot, this.core as OpenACPCore);
 265→    setupActionCallbacks(
 266→      this.bot,
 267→      this.core as OpenACPCore,
 268→      this.telegramConfig.chatId,
 269→      () => this.assistantSession?.id,
 270→    );
 271→    setupIntegrateCallbacks(this.bot, this.core as OpenACPCore);
 272→    setupMenuCallbacks(
 273→      this.bot,
 274→      this.core as OpenACPCore,
 275→      this.telegramConfig.chatId,
 276→      {
 277→        notificationTopicId: this.notificationTopicId,
 278→        assistantTopicId: this.assistantTopicId,
 279→      },
 280→      () => {
 281→        if (!this.assistantSession) return undefined;
 282→        return {
 283→          topicId: this.assistantTopicId,
 284→          enqueuePrompt: (p: string) => this.assistantSession!.enqueuePrompt(p),
 285→        };
 286→      },
 287→    );
 288→    setupCommands(
 289→      this.bot,
 290→      this.core as OpenACPCore,
 291→      this.telegramConfig.chatId,
 292→      {
 293→        topicId: this.assistantTopicId,
 294→        getSession: () => this.assistantSession,
 295→        respawn: async () => {
 296→          if (this.assistantSession) {
 297→            await this.assistantSession.destroy();
 298→            this.assistantSession = null;
 299→          }
 300→          const { session, ready } = await spawnAssistant(
 301→            this.core as OpenACPCore,
 302→            this,
 303→            this.assistantTopicId,
 304→          );
 305→          this.assistantSession = session;
 306→          this.assistantInitializing = true;
 307→          ready.then(() => {
 308→            this.assistantInitializing = false;
 309→          });
 310→        },
 311→      },
 312→    );
 313→    this.permissionHandler.setupCallbackHandler();
 314→
 315→    // /handoff command
 316→    this.bot.command("handoff", async (ctx) => {
 317→      const threadId = ctx.message?.message_thread_id;
 318→      if (!threadId) return;
 319→
 320→      if (
 321→        threadId === this.notificationTopicId ||
 322→        threadId === this.assistantTopicId
 323→      ) {
 324→        await ctx.reply("This command only works in session topics.", {
 325→          message_thread_id: threadId,
 326→        });
 327→        return;
 328→      }
 329→
 330→      const session = this.core.sessionManager.getSessionByThread(
 331→        "telegram",
 332→        String(threadId),
 333→      );
 334→      const record = session
 335→        ? undefined
 336→        : this.core.sessionManager.getRecordByThread(
 337→            "telegram",
 338→            String(threadId),
 339→          );
 340→
 341→      const agentName = session?.agentName ?? record?.agentName;
 342→      const agentSessionId = session?.agentSessionId ?? record?.agentSessionId;
 343→
 344→      if (!agentName || !agentSessionId) {
 345→        await ctx.reply("No session found for this topic.", {
 346→          message_thread_id: threadId,
 347→        });
 348→        return;
 349→      }
 350→
 351→      const { getAgentCapabilities } =
 352→        await import("../../core/agents/agent-registry.js");
 353→      const caps = getAgentCapabilities(agentName);
 354→
 355→      if (!caps.supportsResume || !caps.resumeCommand) {
 356→        await ctx.reply("This agent does not support session transfer.", {
 357→          message_thread_id: threadId,
 358→        });
 359→        return;
 360→      }
 361→
 362→      const command = caps.resumeCommand(agentSessionId);
 363→
 364→      await ctx.reply(
 365→        `Run this in your terminal to continue the session:\n\n<code>${command}</code>`,
 366→        {
 367→          message_thread_id: threadId,
 368→          parse_mode: "HTML",
 369→        },
 370→      );
 371→    });
 372→
 373→    // Setup message routing
 374→    this.setupRoutes();
 375→
 376→    // Start bot polling
 377→    this.bot.start({
 378→      allowed_updates: ["message", "callback_query"],
 379→      onStart: () =>
 380→        log.info(
 381→          { chatId: this.telegramConfig.chatId },
 382→          "Telegram bot started",
 383→        ),
 384→    });
 385→
 386→    // Send welcome message
 387→    try {
 388→      const config = this.core.configManager.get();
 389→      const agents = this.core.agentManager.getAvailableAgents();
 390→      const allRecords = this.core.sessionManager.listRecords();
 391→
 392→      const welcomeText = buildWelcomeMessage({
 393→        activeCount: allRecords.filter(
 394→          (r) => r.status === "active" || r.status === "initializing",
 395→        ).length,
 396→        errorCount: allRecords.filter((r) => r.status === "error").length,
 397→        totalCount: allRecords.length,
 398→        agents: agents.map((a) => a.name),
 399→        defaultAgent: config.defaultAgent,
 400→      });
 401→
 402→      await this.bot.api.sendMessage(this.telegramConfig.chatId, welcomeText, {
 403→        message_thread_id: this.assistantTopicId,
 404→        parse_mode: "HTML",
 405→        reply_markup: buildMenuKeyboard(),
 406→      });
 407→    } catch (err) {
 408→      log.warn({ err }, "Failed to send welcome message");
 409→    }
 410→
 411→    // Spawn assistant in background
 412→    try {
 413→      log.info("Spawning assistant session...");
 414→      const { session, ready } = await spawnAssistant(
 415→        this.core as OpenACPCore,
 416→        this,
 417→        this.assistantTopicId,
 418→      );
 419→      this.assistantSession = session;
 420→      this.assistantInitializing = true;
 421→      log.info(
 422→        { sessionId: session.id },
 423→        "Assistant session ready, system prompt running in background",
 424→      );
 425→      ready.then(() => {
 426→        this.assistantInitializing = false;
 427→        log.info(
 428→          { sessionId: session.id },
 429→          "Assistant ready for user messages",
 430→        );
 431→      });
 432→    } catch (err) {
 433→      log.error({ err }, "Failed to spawn assistant");
 434→      this.bot.api
 435→        .sendMessage(
 436→          this.telegramConfig.chatId,
 437→          `⚠️ <b>Failed to start assistant session.</b>\n\n<code>${err instanceof Error ? err.message : String(err)}</code>`,
 438→          { message_thread_id: this.assistantTopicId, parse_mode: "HTML" },
 439→        )
 440→        .catch(() => {});
 441→    }
 442→  }
