 452→  private setupRoutes(): void {
 453→    this.bot.on("message:text", async (ctx) => {
 454→      const threadId = ctx.message.message_thread_id;
 455→      const text = ctx.message.text;
 456→
 457→      // Check for pending workspace input from interactive /new flow
 458→      if (
 459→        await handlePendingWorkspaceInput(
 460→          ctx,
 461→          this.core,
 462→          this.telegramConfig.chatId,
 463→          this.assistantTopicId,
 464→        )
 465→      ) {
 466→        return;
 467→      }
 468→
 469→      // Check for pending workspace input from interactive /resume flow
 470→      if (
 471→        await handlePendingResumeInput(
 472→          ctx,
 473→          this.core,
 474→          this.telegramConfig.chatId,
 475→          this.assistantTopicId,
 476→        )
 477→      ) {
 478→        return;
 479→      }
 480→
 481→      // General topic or no thread → redirect to assistant
 482→      if (!threadId) {
 483→        const html = redirectToAssistant(
 484→          this.telegramConfig.chatId,
 485→          this.assistantTopicId,
 486→        );
 487→        await ctx.reply(html, { parse_mode: "HTML" });
 488→        return;
 489→      }
 490→
 491→      // Notification topic → ignore
 492→      if (threadId === this.notificationTopicId) return;
 493→
 494→      // Strip leading "/" from unrecognized commands — registered commands
 495→      // (e.g. /new, /cancel) are already handled by bot.command() above.
 496→      // Unrecognized slash commands can cause agent subprocesses to hang.
 497→      const forwardText = text.startsWith("/") ? text.slice(1) : text;
 498→
 499→      // Assistant topic → forward to assistant session
 500→      if (threadId === this.assistantTopicId) {
 501→        if (!this.assistantSession) {
 502→          await ctx.reply(
 503→            "⚠️ Assistant is not available yet. Please try again shortly.",
 504→            { parse_mode: "HTML" },
 505→          );
 506→          return;
 507→        }
 508→        await this.draftManager.finalize(
 509→          this.assistantSession.id,
 510→          this.assistantSession.id,
 511→        );
 512→        ctx.replyWithChatAction("typing").catch(() => {});
 513→        handleAssistantMessage(this.assistantSession, forwardText).catch(
 514→          (err) => log.error({ err }, "Assistant error"),
 515→        );
 516→        return;
 517→      }
 518→
 519→      // Session topic → forward to core
 520→      const sessionId = this.core.sessionManager.getSessionByThread(
 521→        "telegram",
 522→        String(threadId),
 523→      )?.id;
 524→      if (sessionId)
 525→        await this.draftManager.finalize(sessionId, this.assistantSession?.id);
 526→      if (sessionId) {
 527→        const tracker = this.sessionTrackers.get(sessionId);
 528→        if (tracker) await tracker.onNewPrompt();
 529→      }
 530→      ctx.replyWithChatAction("typing").catch(() => {});
 531→      this.core
 532→        .handleMessage({
 533→          channelId: "telegram",
 534→          threadId: String(threadId),
 535→          userId: String(ctx.from.id),
 536→          text: forwardText,
 537→        })
 538→        .catch((err) => log.error({ err }, "handleMessage error"));
 539→    });
 540→
 541→    // --- Incoming media handlers ---
 542→
 543→    this.bot.on("message:photo", async (ctx) => {
 544→      const threadId = ctx.message.message_thread_id;
 545→      if (!threadId || threadId === this.notificationTopicId) return;
 546→
 547→      const photos = ctx.message.photo;
 548→      const largest = photos[photos.length - 1];
 549→      const ext = ".jpg";
 550→      await this.handleIncomingMedia(
 551→        threadId,
 552→        ctx.from.id,
 553→        largest.file_id,
 554→        `photo${ext}`,
 555→        "image/jpeg",
 556→        ctx.message.caption || undefined,
 557→      );
 558→    });
 559→
 560→    this.bot.on("message:document", async (ctx) => {
 561→      const threadId = ctx.message.message_thread_id;
 562→      if (!threadId || threadId === this.notificationTopicId) return;
 563→
 564→      const doc = ctx.message.document;
 565→      await this.handleIncomingMedia(
 566→        threadId,
 567→        ctx.from.id,
 568→        doc.file_id,
 569→        doc.file_name || "document",
 570→        doc.mime_type || "application/octet-stream",
 571→        ctx.message.caption || undefined,
 572→      );
 573→    });
 574→
 575→    this.bot.on("message:voice", async (ctx) => {
 576→      const threadId = ctx.message.message_thread_id;
 577→      if (!threadId || threadId === this.notificationTopicId) return;
 578→
 579→      const voice = ctx.message.voice;
 580→      await this.handleIncomingMedia(
 581→        threadId,
 582→        ctx.from.id,
 583→        voice.file_id,
 584→        "voice.wav",
 585→        "audio/wav",
 586→        undefined,
 587→        true,
 588→      );
 589→    });
 590→
 591→    this.bot.on("message:audio", async (ctx) => {
 592→      const threadId = ctx.message.message_thread_id;
 593→      if (!threadId || threadId === this.notificationTopicId) return;
 594→
 595→      const audio = ctx.message.audio;
 596→      await this.handleIncomingMedia(
 597→        threadId,
 598→        ctx.from.id,
 599→        audio.file_id,
 600→        audio.file_name || "audio.mp3",
 601→        audio.mime_type || "audio/mpeg",
 602→        ctx.message.caption || undefined,
 603→      );
 604→    });
 605→
 606→    this.bot.on("message:video_note", async (ctx) => {
 607→      const threadId = ctx.message.message_thread_id;
 608→      if (!threadId || threadId === this.notificationTopicId) return;
 609→
 610→      const videoNote = ctx.message.video_note;
 611→      await this.handleIncomingMedia(
 612→        threadId,
 613→        ctx.from.id,
 614→        videoNote.file_id,
 615→        "video_note.mp4",
 616→        "video/mp4",
 617→      );
 618→    });
 619→  }
