 741→  protected async handleUsage(sessionId: string, content: OutgoingMessage, verbosity: DisplayVerbosity): Promise<void> {
 742→    const threadId = this.getThreadId(sessionId);
 743→    const meta = content.metadata as UsageMetadata | undefined;
 744→    await this.draftManager.finalize(
 745→      sessionId,
 746→      this.assistantSession?.id,
 747→    );
 748→    const tracker = this.getOrCreateTracker(sessionId, threadId);
 749→    await tracker.sendUsage(meta ?? {}, verbosity);
 750→
 751→    // Notify the Notifications topic that a prompt has completed
 752→    if (
 753→      this.notificationTopicId &&
 754→      sessionId !== this.assistantSession?.id
 755→    ) {
 756→      const sess = this.core.sessionManager.getSession(sessionId);
 757→      const sessionName = sess?.name || "Session";
 758→      const chatIdStr = String(this.telegramConfig.chatId);
 759→      const numericId = chatIdStr.startsWith("-100")
 760→        ? chatIdStr.slice(4)
 761→        : chatIdStr.replace("-", "");
 762→      const usageMsgId = tracker.getUsageMsgId();
 763→      const deepLink = usageMsgId
 764→        ? `https://t.me/c/${numericId}/${threadId}/${usageMsgId}`
 765→        : `https://t.me/c/${numericId}/${threadId}`;
 766→      const text = `✅ <b>${escapeHtml(sessionName)}</b>\nTask completed.\n\n<a href="${deepLink}">→ Go to topic</a>`;
 767→      this.sendQueue
 768→        .enqueue(() =>
 769→          this.bot.api.sendMessage(this.telegramConfig.chatId, text, {
 770→            message_thread_id: this.notificationTopicId,
 771→            parse_mode: "HTML",
 772→            disable_notification: false,
 773→          }),
 774→        )
 775→        .catch(() => {});
 776→    }
 777→  }
