 956→    const replyMarkup =
 957→      notification.type === "completed"
 958→        ? {
 959→            inline_keyboard: [
 960→              [
 961→                {
 962→                  text: "📋 Summary",
 963→                  callback_data: `sm:summary:${notification.sessionId}`,
 964→                },
 965→              ],
 966→            ],
 967→          }
 968→        : undefined;
