1038→  private async downloadTelegramFile(
1039→    fileId: string,
1040→  ): Promise<{ buffer: Buffer; filePath: string } | null> {
1041→    try {
1042→      const file = await this.bot.api.getFile(fileId);
1043→      if (!file.file_path) return null;
1044→      const url = `https://api.telegram.org/file/bot${this.telegramConfig.botToken}/${file.file_path}`;
1045→      const response = await fetch(url);
1046→      if (!response.ok) return null;
1047→      const buffer = Buffer.from(await response.arrayBuffer());
1048→      return { buffer, filePath: file.file_path };
1049→    } catch (err) {
1050→      log.error({ err }, "Failed to download file from Telegram");
1051→      return null;
1052→    }
1053→  }
