  7→export function registerSessionRoutes(router: Router, deps: RouteDeps): void {
  8→  router.post("/api/sessions/adopt", async (req, res) => {
  9→    const body = await deps.readBody(req);
 10→    if (body === null) {
 11→      return deps.sendJson(res, 413, { error: "Request body too large" });
 12→    }
 13→    if (!body) {
 14→      return deps.sendJson(res, 400, {
 15→        error: "bad_request",
 16→        message: "Empty request body",
 17→      });
 18→    }
 19→
 20→    let parsed: { agent?: string; agentSessionId?: string; cwd?: string; channel?: string };
 21→    try {
 22→      parsed = JSON.parse(body);
 23→    } catch {
 24→      return deps.sendJson(res, 400, {
 25→        error: "bad_request",
 26→        message: "Invalid JSON",
 27→      });
 28→    }
 29→
 30→    const { agent, agentSessionId, cwd, channel } = parsed;
 31→
 32→    if (!agent || !agentSessionId) {
 33→      return deps.sendJson(res, 400, {
 34→        error: "bad_request",
 35→        message: "Missing required fields: agent, agentSessionId",
 36→      });
 37→    }
 38→
 39→    const result = await deps.core.adoptSession(
 40→      agent,
 41→      agentSessionId,
 42→      cwd ?? process.cwd(),
 43→      channel,
 44→    );
 45→
 46→    if (result.ok) {
 47→      return deps.sendJson(res, 200, result);
 48→    } else {
 49→      const status =
 50→        result.error === "session_limit"
 51→          ? 429
 52→          : result.error === "agent_not_supported"
 53→            ? 400
 54→            : 500;
 55→      return deps.sendJson(res, status, result);
 56→    }
 57→  });
 58→
 59→  router.post("/api/sessions", async (req, res) => {
 60→    const body = await deps.readBody(req);
 61→    let agent: string | undefined;
 62→    let workspace: string | undefined;
 63→    let channel: string | undefined;
 64→
 65→    if (body) {
 66→      try {
 67→        const parsed = JSON.parse(body);
 68→        agent = parsed.agent;
 69→        workspace = parsed.workspace;
 70→        channel = parsed.channel;
 71→      } catch {
 72→        deps.sendJson(res, 400, { error: "Invalid JSON body" });
 73→        return;
 74→      }
 75→    }
 76→
 77→    // Check max concurrent sessions
 78→    const config = deps.core.configManager.get();
 79→    const activeSessions = deps.core.sessionManager
 80→      .listSessions()
 81→      .filter((s) => s.status === "active" || s.status === "initializing");
 82→    if (activeSessions.length >= config.security.maxConcurrentSessions) {
 83→      deps.sendJson(res, 429, {
 84→        error: `Max concurrent sessions (${config.security.maxConcurrentSessions}) reached. Cancel a session first.`,
 85→      });
 86→      return;
 87→    }
 88→
 89→    // Resolve adapter: use explicit channel if provided, otherwise fall back to first registered adapter
 90→    let adapterId: string | null = null;
 91→    let adapter: InstanceType<any> | null = null;
 92→
 93→    if (channel) {
 94→      if (!deps.core.adapters.has(channel)) {
 95→        const available = Array.from(deps.core.adapters.keys()).join(", ") || "none";
 96→        deps.sendJson(res, 400, {
 97→          error: `Adapter '${channel}' is not connected. Available: ${available}`,
 98→        });
 99→        return;
100→      }
101→      adapterId = channel;
102→      adapter = deps.core.adapters.get(channel) ?? null;
103→    } else {
104→      const firstEntry = deps.core.adapters.entries().next().value;
105→      if (firstEntry) {
106→        [adapterId, adapter] = firstEntry;
107→      }
108→    }
109→
110→    const channelId = adapterId ?? "api";
111→
112→    const resolvedAgent = agent || config.defaultAgent;
113→    const resolvedWorkspace = deps.core.configManager.resolveWorkspace(
114→      workspace || config.agents[resolvedAgent]?.workingDirectory,
115→    );
116→
117→    const session = await deps.core.createSession({
118→      channelId,
119→      agentName: resolvedAgent,
120→      workingDirectory: resolvedWorkspace,
121→      createThread: !!adapter,
122→      initialName: `🔄 ${resolvedAgent} — New Session`,
123→    });
124→
125→    // If no adapter wired events (headless), auto-approve permissions
126→    if (!adapter) {
127→      session.agentInstance.onPermissionRequest = async (request) => {
128→        const allowOption = request.options.find((o) => o.isAllow);
129→        log.debug(
130→          {
131→            sessionId: session.id,
132→            permissionId: request.id,
133→            option: allowOption?.id,
134→          },
135→          "Auto-approving permission for API session",
136→        );
137→        return allowOption?.id ?? request.options[0]?.id ?? "";
138→      };
139→    }
140→
141→    // Warmup in background so session moves from 'initializing' to 'active'
142→    session
143→      .warmup()
144→      .catch((err) =>
145→        log.warn({ err, sessionId: session.id }, "API session warmup failed"),
146→      );
147→
148→    deps.sendJson(res, 200, {
149→      sessionId: session.id,
150→      agent: session.agentName,
151→      status: session.status,
152→      workspace: session.workingDirectory,
153→    });
154→  });
