156→  router.post("/api/sessions/:sessionId/prompt", async (req, res, params) => {
157→    const sessionId = decodeURIComponent(params.sessionId);
158→    const session = deps.core.sessionManager.getSession(sessionId);
159→    if (!session) {
160→      deps.sendJson(res, 404, { error: `Session "${sessionId}" not found` });
161→      return;
162→    }
163→
164→    if (
165→      session.status === "cancelled" ||
166→      session.status === "finished" ||
167→      session.status === "error"
168→    ) {
169→      deps.sendJson(res, 400, { error: `Session is ${session.status}` });
170→      return;
171→    }
172→
173→    const body = await deps.readBody(req);
174→    let prompt: string | undefined;
175→    if (body) {
176→      try {
177→        const parsed = JSON.parse(body);
178→        prompt = parsed.prompt;
179→      } catch {
180→        deps.sendJson(res, 400, { error: "Invalid JSON body" });
181→        return;
182→      }
183→    }
184→
185→    if (!prompt) {
186→      deps.sendJson(res, 400, { error: "Missing prompt" });
187→      return;
188→    }
189→
190→    session.enqueuePrompt(prompt).catch(() => {});
191→    deps.sendJson(res, 200, {
192→      ok: true,
193→      sessionId,
194→      queueDepth: session.queueDepth,
195→    });
196→  });
197→
198→  router.post(
199→    "/api/sessions/:sessionId/permission",
200→    async (req, res, params) => {
201→      const sessionId = decodeURIComponent(params.sessionId);
202→      const session = deps.core.sessionManager.getSession(sessionId);
203→      if (!session) {
204→        deps.sendJson(res, 404, { error: `Session "${sessionId}" not found` });
205→        return;
206→      }
207→
208→      const body = await deps.readBody(req);
209→      let permissionId: string | undefined;
210→      let optionId: string | undefined;
211→      if (body) {
212→        try {
213→          const parsed = JSON.parse(body);
214→          permissionId = parsed.permissionId;
215→          optionId = parsed.optionId;
216→        } catch {
217→          deps.sendJson(res, 400, { error: "Invalid JSON body" });
218→          return;
219→        }
220→      }
221→
222→      if (!permissionId || !optionId) {
223→        deps.sendJson(res, 400, {
224→          error: "Missing permissionId or optionId",
225→        });
226→        return;
227→      }
228→
229→      if (
230→        !session.permissionGate.isPending ||
231→        session.permissionGate.requestId !== permissionId
232→      ) {
233→        deps.sendJson(res, 400, {
234→          error: "No matching pending permission request",
235→        });
236→        return;
237→      }
238→
239→      session.permissionGate.resolve(optionId);
240→      deps.sendJson(res, 200, { ok: true });
241→    },
242→  );
