261→          deps.sendJson(res, 400, { error: "Invalid JSON body" });
262→          return;
263→        }
264→      }
265→
266→      if (typeof enabled !== "boolean") {
267→        deps.sendJson(res, 400, { error: "Missing enabled boolean" });
268→        return;
269→      }
270→
271→      session.dangerousMode = enabled;
272→      await deps.core.sessionManager.patchRecord(sessionId, {
273→        dangerousMode: enabled,
274→      });
275→      deps.sendJson(res, 200, { ok: true, dangerousMode: enabled });
276→    },
277→  );
