 8→export function readApiPort(portFilePath: string = DEFAULT_PORT_FILE): number | null {
 9→  try {
10→    const content = fs.readFileSync(portFilePath, 'utf-8').trim()
11→    const port = parseInt(content, 10)
12→    return isNaN(port) ? null : port
13→  } catch {
14→    return null
15→  }
16→}
17→
18→export function readApiSecret(secretFilePath: string = DEFAULT_SECRET_FILE): string | null {
19→  try {
20→    const content = fs.readFileSync(secretFilePath, 'utf-8').trim()
21→    return content || null
22→  } catch {
23→    return null
24→  }
25→}
26→
27→export function removeStalePortFile(portFilePath: string = DEFAULT_PORT_FILE): void {
28→  try {
29→    fs.unlinkSync(portFilePath)
30→  } catch {
31→    // ignore
32→  }
33→}
34→
35→export async function apiCall(
36→  port: number,
37→  urlPath: string,
38→  options?: RequestInit,
39→): Promise<Response> {
40→  const secret = readApiSecret()
41→  const headers = new Headers(options?.headers)
42→  if (secret) {
43→    headers.set('Authorization', `Bearer ${secret}`)
44→  }
45→  return fetch(`http://127.0.0.1:${port}${urlPath}`, { ...options, headers })
46→}
