 25→export interface CleanupResult {
 26→  deleted: string[]
 27→  failed: { sessionId: string; error: string }[]
 28→}
 29→
 30→interface SystemTopicIds {
 31→  notificationTopicId: number | null
 32→  assistantTopicId: number | null
 33→}
 34→
 35→export class TopicManager {
 36→  constructor(
 37→    private sessionManager: SessionManager,
 38→    private adapter: IChannelAdapter | null,
 39→    private systemTopicIds: SystemTopicIds,
 40→  ) {}
 41→
 42→  listTopics(filter?: { statuses?: string[] }): TopicInfo[] {
 43→    const records = this.sessionManager.listRecords(filter)
 44→    return records
 45→      .filter(r => !this.isSystemTopic(r))
 46→      .filter(r => !filter?.statuses?.length || filter.statuses.includes(r.status))
 47→      .map(r => ({
 48→        sessionId: r.sessionId,
 49→        topicId: (r.platform as Record<string, unknown>)?.topicId as number ?? null,
 50→        name: r.name ?? null,
 51→        status: r.status,
 52→        agentName: r.agentName,
 53→        lastActiveAt: r.lastActiveAt,
 54→      }))
 55→  }
 56→
 57→  async deleteTopic(sessionId: string, options?: { confirmed?: boolean }): Promise<DeleteTopicResult> {
 58→    const records = this.sessionManager.listRecords()
 59→    const record = records.find(r => r.sessionId === sessionId)
 60→    if (!record) return { ok: false, error: 'Session not found' }
 61→
 62→    if (this.isSystemTopic(record)) return { ok: false, error: 'Cannot delete system topic' }
 63→
 64→    const isActive = record.status === 'active' || record.status === 'initializing'
 65→    if (isActive && !options?.confirmed) {
 66→      return {
 67→        ok: false,
 68→        needsConfirmation: true,
 69→        session: { id: record.sessionId, name: record.name ?? null, status: record.status },
 70→      }
 71→    }
 72→
 73→    if (isActive) {
 74→      await this.sessionManager.cancelSession(sessionId)
 75→    }
 76→
 77→    const topicId = (record.platform as Record<string, unknown>)?.topicId as number ?? null
 78→    if (this.adapter && topicId) {
 79→      try {
 80→        await this.adapter.deleteSessionThread?.(sessionId)
 81→      } catch (err) {
 82→        log.warn({ err, sessionId, topicId }, 'Failed to delete platform thread, removing record anyway')
 83→      }
 84→    }
 85→
 86→    await this.sessionManager.removeRecord(sessionId)
 87→    return { ok: true, topicId }
 88→  }
 89→
 90→  async cleanup(statuses?: string[]): Promise<CleanupResult> {
 91→    const targetStatuses = statuses?.length ? statuses : ['finished', 'error', 'cancelled']
 92→    const records = this.sessionManager.listRecords({ statuses: targetStatuses })
 93→    const targets = records
 94→      .filter(r => !this.isSystemTopic(r))
 95→      .filter(r => targetStatuses.includes(r.status))
 96→
 97→    const deleted: string[] = []
 98→    const failed: { sessionId: string; error: string }[] = []
 99→
100→    for (const record of targets) {
101→      try {
102→        // Cancel active/initializing sessions to prevent orphaned agent processes
103→        const isActive = record.status === 'active' || record.status === 'initializing'
104→        if (isActive) {
105→          await this.sessionManager.cancelSession(record.sessionId)
106→        }
107→
108→        const topicId = (record.platform as Record<string, unknown>)?.topicId as number | undefined
109→        if (this.adapter && topicId) {
110→          try {
111→            await this.adapter.deleteSessionThread?.(record.sessionId)
112→          } catch (err) {
113→            log.warn({ err, sessionId: record.sessionId }, 'Failed to delete platform thread during cleanup')
114→          }
115→        }
116→        await this.sessionManager.removeRecord(record.sessionId)
117→        deleted.push(record.sessionId)
118→      } catch (err) {
119→        failed.push({ sessionId: record.sessionId, error: err instanceof Error ? err.message : String(err) })
120→      }
121→    }
122→
123→    return { deleted, failed }
124→  }
125→
126→  private isSystemTopic(record: SessionRecord): boolean {
127→    const topicId = (record.platform as Record<string, unknown>)?.topicId as number | undefined
128→    if (!topicId) return false
129→    return topicId === this.systemTopicIds.notificationTopicId
130→      || topicId === this.systemTopicIds.assistantTopicId
131→  }
132→}
